// ══════════════════════════════════════════════════════
// 🚀 AUTO-INSTALL BOOTSTRAP
// Automatically runs npm install if any dependency is missing
// (no SSH terminal needed on first deploy to Hostinger)
// ══════════════════════════════════════════════════════
(function autoInstallDependencies() {
  // Skip on Vercel/serverless — filesystem is read-only and deps are pre-installed during build.
  if (process.env.VERCEL || process.env.AWS_LAMBDA_FUNCTION_NAME) return;

  const fs = require('fs');
  const path = require('path');
  const { execSync } = require('child_process');

  const pkgPath = path.join(__dirname, 'package.json');
  const nodeModulesPath = path.join(__dirname, 'node_modules');

  if (!fs.existsSync(pkgPath)) return; // safety guard

  let needsInstall = false;
  let missingPkg = '';

  try {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    const deps = Object.keys(pkg.dependencies || {});

    // Check 1: node_modules folder exists?
    if (!fs.existsSync(nodeModulesPath)) {
      needsInstall = true;
    } else {
      // Check 2: Are all dependencies present in node_modules?
      for (const dep of deps) {
        if (!fs.existsSync(path.join(nodeModulesPath, dep))) {
          needsInstall = true;
          missingPkg = dep;
          break;
        }
      }
    }
  } catch (err) {
    console.error('  ⚠️  package.json read error:', err.message);
    return;
  }

  if (needsInstall) {
    console.log('  📦 Dependencies missing' + (missingPkg ? ` (${missingPkg})` : '') + ' — installing...');
    console.log('  ⏳ This may take 1-2 minutes, please wait...');
    try {
      execSync('npm install --production --no-audit --no-fund', {
        stdio: 'inherit',
        cwd: __dirname
      });
      console.log('  ✅ Dependencies installed successfully!');
    } catch (err) {
      console.error('  ❌ npm install failed:', err.message);
      console.error('  ⚠️  Please run "npm install" manually via SSH/Terminal');
      process.exit(1);
    }
  }
})();

require('dotenv').config();
const express = require('express');
const bcrypt = require('bcryptjs'); // only for comparing legacy bcrypt hashes (auto-migrate)
const jwt = require('jsonwebtoken');
const path = require('path');
const nodemailer = require('nodemailer');
const crypto = require('crypto');

// Passwords are stored as bcrypt hashes. Some rows may still hold a plaintext
// value left over from before hashing was added — a successful plaintext
// match is auto-migrated to a hash on login (see /api/login) so every
// account converges to a hash over time without a forced reset.
function checkPassword(plain, stored) {
  if (!stored || plain == null) return { ok: false };
  if (/^\$2[aby]\$/.test(stored)) {
    try { return { ok: bcrypt.compareSync(plain, stored), legacy: false }; }
    catch(_) { return { ok: false }; }
  }
  if (plain === stored) return { ok: true, legacy: true };
  return { ok: false };
}
function hashPassword(plain) {
  return bcrypt.hashSync(plain, 10);
}

const app = express();
const PORT = process.env.PORT || 3000;
let JWT_SECRET = process.env.SESSION_SECRET;
if (!JWT_SECRET) {
  if (process.env.NODE_ENV === 'production') {
    // Refuse to boot rather than silently sign JWTs (including admin logins)
    // with a secret anyone with repo access could read and forge tokens with.
    console.error('  ❌ SESSION_SECRET is not set. Refusing to start in production — set it in your environment.');
    process.exit(1);
  }
  console.warn('  ⚠️  SESSION_SECRET is not set — using an insecure development-only fallback. Set SESSION_SECRET before deploying.');
  JWT_SECRET = 'dev_only_insecure_secret_do_not_use_in_production';
}

// ── Vercel free plan: only ~4 h of server CPU a month (the site was paused
// on 2026-10-09 for going over). Keep server work small: ──
// 1) Log any request that burns a lot of CPU, so heavy endpoints show up in
//    `vercel logs`. Approximate when requests overlap on one instance.
app.use((req, res, next) => {
  const t0 = process.cpuUsage();
  res.on('finish', () => {
    const d = process.cpuUsage(t0);
    const ms = Math.round((d.user + d.system) / 1000);
    if (ms >= 150) console.log(`[cpu] ${ms}ms ${req.method} ${req.path} ${res.statusCode}`);
  });
  next();
});
// 2) Pages and static files are the same for everyone (login is checked by
//    /api/me), so Vercel's CDN may keep them: s-maxage lets the CDN answer
//    without running the function, max-age=0 makes browsers re-check every
//    time, and a new deployment clears the CDN — users still get new code.
const CDN_CACHE = 'public, max-age=0, s-maxage=31536000';

// Basic browser hardening (vendor portal is used from outside the company):
// no framing by other sites, no MIME sniffing, no full URLs leaked onward.
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'SAMEORIGIN');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// 3) Sheet-backed FMS reads (O2D, Service, Purchase) are cached per instance,
//    but kept right across Vercel instances: every successful write under the
//    routes below bumps a version in app_settings ('ver_<key>') BEFORE its
//    response goes out, and a cached copy is used only while the version still
//    matches. (A plain TTL cache made "Mark Done" look lost on other
//    instances.) The TTL only bounds edits made straight in the sheet / forms.
//    Re-reading these sheets on every call was most of the CPU (2026-10-24).
const SHEET_VER_ROUTES = [
  ['/api/o2d-fms', 'o2d'], ['/api/service-fms', 'sfms'],
  ['/api/purchase-fms', 'purchase'], ['/api/stock', 'purchase'], ['/api/vendor', 'purchase'],
];
const SHEET_CACHE_TTL_MS = 3 * 60 * 1000;
const _sheetVerCache = new Map(); // key -> { ver, ts, data }
async function sheetVer(key) {
  const [[r]] = await db.query('SELECT setting_value AS v FROM app_settings WHERE setting_key=?', [`ver_${key}`]);
  return r ? String(r.v) : '';
}
function bumpSheetVer(key) {
  _sheetVerCache.delete(key);
  return db.query(
    'INSERT INTO app_settings (setting_key, setting_value) VALUES (?, ?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',
    [`ver_${key}`, `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`]);
}
// load() runs on a miss. clone=true when callers mutate what they get back.
async function cachedBySheetVer(key, load, clone = false) {
  let ver = null;
  try { ver = await sheetVer(key); } catch (e) { console.error(`ver_${key} read:`, e.message); }
  const c = _sheetVerCache.get(key);
  if (ver !== null && c && c.ver === ver && Date.now() - c.ts < SHEET_CACHE_TTL_MS) return clone ? structuredClone(c.data) : c.data;
  const data = await load();
  if (ver !== null) _sheetVerCache.set(key, { ver, ts: Date.now(), data: clone ? structuredClone(data) : data });
  return data;
}
app.use((req, res, next) => {
  if (req.method === 'GET') return next();
  const keys = [...new Set(SHEET_VER_ROUTES.filter(([p]) => req.path === p || req.path.startsWith(p + '/')).map(([, k]) => k))];
  if (!keys.length) return next();
  keys.forEach(k => _sheetVerCache.delete(k));
  const json = res.json.bind(res);
  res.json = body => {
    if (res.statusCode >= 400) return json(body);
    Promise.all(keys.map(bumpSheetVer)).catch(e => console.error('sheet ver bump:', e.message)).finally(() => json(body));
    return res;
  };
  next();
});

const cookieParser = require('cookie-parser');
app.use(cookieParser());
app.use(express.json({ limit: '100mb' }));
app.use(express.urlencoded({ extended: true, limit: '100mb' }));
app.use(express.static(path.join(__dirname, 'public'), { setHeaders: r => r.setHeader('Cache-Control', CDN_CACHE) }));

// ══════════════════════════════════════════════════════
// LIGHTWEIGHT RATE LIMITING — in-memory per-process sliding window, used on
// login and OTP verification (previously unprotected against brute force).
// On a single always-on instance (the traditional/Hostinger deploy target)
// this is a real limiter; on multi-instance serverless it's best-effort
// only, since each instance keeps its own counters — the same inherent
// limitation already documented for sheets-db.js's in-memory state.
// ══════════════════════════════════════════════════════
const _rateLimitHits = new Map(); // key -> [timestamps]
function rateLimit(keyFn, max, windowMs) {
  return (req, res, next) => {
    const key = keyFn(req);
    const now = Date.now();
    const hits = (_rateLimitHits.get(key) || []).filter(t => now - t < windowMs);
    if (hits.length >= max) {
      return res.status(429).json({ error: 'Too many attempts — please wait a bit and try again.' });
    }
    hits.push(now);
    _rateLimitHits.set(key, hits);
    next();
  };
}
setInterval(() => {
  const cutoff = Date.now() - 15 * 60 * 1000;
  for (const [key, hits] of _rateLimitHits) {
    const fresh = hits.filter(t => t > cutoff);
    if (fresh.length) _rateLimitHits.set(key, fresh); else _rateLimitHits.delete(key);
  }
}, 5 * 60 * 1000).unref();
// Non-middleware variant — for rate-limiting a specific branch inside a
// handler (e.g. only the OTP-check code path of a multi-purpose route)
// rather than the whole route.
function isRateLimited(key, max, windowMs) {
  const now = Date.now();
  const hits = (_rateLimitHits.get(key) || []).filter(t => now - t < windowMs);
  hits.push(now);
  _rateLimitHits.set(key, hits);
  return hits.length > max;
}

// ══════════════════════════════════════════════════════
// DATABASE — real MySQL when DB_HOST is set, else the Google Sheets
// backed in-memory adapter (sheets-db.js is a drop-in stand-in for the
// same mysql2/promise db.query / db.execute / db.getConnection API).
// ══════════════════════════════════════════════════════
const _usingMysql = !!process.env.DB_HOST;
const db = _usingMysql ? require('./mysql-db') : require('./sheets-db');
const _dbReady = db.init()
  .then(async () => {
    console.log(_usingMysql ? '  ✅ MySQL DB ready' : '  ✅ Sheets DB ready');
    // Migration: set is_active=1 for users where it is null/empty (added after initial deploy)
    try {
      const [rows] = await db.query('SELECT id, is_active FROM users');
      for (const u of rows) {
        if (u.is_active === '' || u.is_active === null || u.is_active === undefined) {
          await db.query('UPDATE users SET is_active=1 WHERE id=?', [u.id]);
        }
      }
    } catch(e) { console.warn('  ⚠️ is_active migration skipped:', e.message); }
    // Migration: add page_access column (per-user page permissions, added after initial deploy)
    if (_usingMysql) {
      try { await db.query('ALTER TABLE users ADD COLUMN page_access TEXT DEFAULT NULL'); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME') console.warn('  ⚠️ page_access migration skipped:', e.message); }
      // Migration: add force_logout_at column (admin-triggered remote sign-out)
      try { await db.query('ALTER TABLE users ADD COLUMN force_logout_at DATETIME DEFAULT NULL'); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME') console.warn('  ⚠️ force_logout_at migration skipped:', e.message); }
      // Migration: add track_km column — a dedicated per-user flag (set from
      // the Users page) for whether Attendance shows the KM Start/End fields,
      // kept separate from the free-text department column on purpose.
      try { await db.query('ALTER TABLE users ADD COLUMN track_km TINYINT DEFAULT 0'); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME') console.warn('  ⚠️ track_km migration skipped:', e.message); }
      // Migration: add photo-proof-of-completion columns to delegation_tasks
      // — attachment_required (set from the Delegate/Edit Task modal) gates
      // whether "Mark Done" first needs a photo upload; attachment_link is
      // the resulting Drive link once one's been provided.
      try { await db.query("ALTER TABLE delegation_tasks ADD COLUMN attachment_required VARCHAR(10) DEFAULT 'no'"); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ attachment_required migration skipped:', e.message); }
      try { await db.query('ALTER TABLE delegation_tasks ADD COLUMN attachment_link TEXT DEFAULT NULL'); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ attachment_link migration skipped:', e.message); }
      // Migration: reference photo attached by whoever delegates the task.
      try { await db.query('ALTER TABLE delegation_tasks ADD COLUMN photo_link TEXT DEFAULT NULL'); }
      catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ photo_link migration skipped:', e.message); }
      // Migration: reference file + voice note attached when delegating.
      for (const col of ['ref_file_link TEXT DEFAULT NULL', 'ref_file_name VARCHAR(255) DEFAULT NULL', 'audio_link TEXT DEFAULT NULL']) {
        try { await db.query(`ALTER TABLE delegation_tasks ADD COLUMN ${col}`); }
        catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ delegation attachment migration skipped:', e.message); }
      }
      // Migration: add GPS columns to an already-created attendance table
      // (a brand new install instead gets them straight from CREATE TABLE
      // in ensureAttendanceTables — ER_NO_SUCH_TABLE here is expected then).
      for (const col of ['lat_in DECIMAL(10,7)', 'lng_in DECIMAL(10,7)', 'lat_out DECIMAL(10,7)', 'lng_out DECIMAL(10,7)']) {
        try { await db.query(`ALTER TABLE attendance ADD COLUMN ${col}`); }
        catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ attendance GPS migration skipped:', e.message); }
      }
      // Migration: add reverse-geocoded address text columns to attendance.
      // KM lives in its own `daily_km` table, not on attendance —
      // the old km_start/km_end columns are left in place, just unused.
      for (const col of ['address_in VARCHAR(500)', 'address_out VARCHAR(500)']) {
        try { await db.query(`ALTER TABLE attendance ADD COLUMN ${col}`); }
        catch(e) { if (e.code !== 'ER_DUP_FIELDNAME' && e.code !== 'ER_NO_SUCH_TABLE') console.warn('  ⚠️ attendance address migration skipped:', e.message); }
      }
    }
  })
  .catch(err => {
    console.error('  ❌ Sheets DB init failed:', err.message);
    console.error('  💡 Set GOOGLE_SHEET_ID in .env and share the sheet with the service account.');
  });

// ══════════════════════════════════════════════════════
// EMAIL CONFIGURATION (Gmail SMTP via Nodemailer)
// ══════════════════════════════════════════════════════
const mailTransporter = nodemailer.createTransport({
  service: 'gmail',
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS
  }
});

(async () => {
  try {
    if (process.env.SMTP_USER && process.env.SMTP_PASS) {
      await mailTransporter.verify();
      console.log('  ✅ Gmail SMTP Ready');
    } else {
      console.log('  ⚠️  SMTP credentials missing — emails disabled');
    }
  } catch (err) {
    console.error('  ❌ SMTP verification failed:', err.message);
  }
})();

// Reusable email sender — never throws (failures are logged only)
async function sendMail(to, subject, html) {
  if (!to || !process.env.SMTP_USER) return;
  try {
    await mailTransporter.sendMail({
      from: `"${process.env.SMTP_FROM_NAME || 'Task Manager'}" <${process.env.SMTP_USER}>`,
      to, subject, html
    });
    console.log(`  📧 Email sent to ${to} — ${subject}`);
  } catch (err) {
    console.error(`  ❌ Email failed (${to}):`, err.message);
  }
}

// Helper: get user's notification email + name
async function getNotifyTarget(userId) {
  try {
    const [rows] = await db.query(
      'SELECT name, notification_email FROM users WHERE id=? LIMIT 1',
      [userId]
    );
    if (!rows[0] || !rows[0].notification_email) return null;
    return { name: rows[0].name, email: rows[0].notification_email };
  } catch { return null; }
}

