app.put('/api/approvals/:id', requireAuth, async (req, res) => {
  try {
    const { action, note } = req.body;
    const role = req.session.role;
    const approvalId = parseInt(req.params.id, 10);
    const [rows] = await db.query('SELECT * FROM task_approvals WHERE id=?', [approvalId]);
    if (!rows[0]) return res.status(404).json({ error: 'Approval not found' });
    const appr = rows[0];
    // PC and admin can approve any; others only their own
    const canApprove = role === 'admin' || role === 'pc' || appr.requested_to === req.session.userId;
    if (!canApprove) return res.status(403).json({ error: 'Not allowed' });
    // Guard against double-processing (two rapid clicks, or a retried
    // request): only actually transition a row that's still 'pending' —
    // the WHERE clause is re-checked atomically by the UPDATE itself, not
    // against the possibly-stale `appr` read above.
    const [updateResult] = await db.query(`UPDATE task_approvals SET status=?,note=? WHERE id=? AND status='pending'`, [action, note||'', approvalId]);
    if (!updateResult.affectedRows) return res.status(400).json({ error: 'This approval has already been processed' });
    const table = getTable(appr.task_type);
    if (action === 'approved') {
      const completedAt = appr.action_type === 'completed' ? new Date().toISOString().slice(0,19).replace('T',' ') : null;
      if (appr.action_type === 'revised') {
        // Revision granted — task goes back to pending with new date, mark revision approved
        await db.query(`UPDATE ${table} SET status='pending',waiting_approval=0,revision_status='approved',completed_at=? WHERE id=?`, [completedAt, appr.task_id]);
      } else {
        await db.query(`UPDATE ${table} SET status=?,waiting_approval=0,revision_status='',completed_at=? WHERE id=?`, [appr.action_type, completedAt, appr.task_id]);
      }
    } else {
      // Rejected — task goes back to pending, mark revision rejected
      if (appr.action_type === 'revised') {
        await db.query(`UPDATE ${table} SET status='pending',waiting_approval=0,revision_status='rejected' WHERE id=?`, [appr.task_id]);
      } else {
        await db.query(`UPDATE ${table} SET waiting_approval=0 WHERE id=?`, [appr.task_id]);
      }
    }
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

// ══════════════════════════════════════════════════════
// ATTENDANCE, LEAVE & RIDES
// - Attendance: daily time-in/time-out punch for every employee.
// - Leave: apply/approve/reject.
// - Daily KM: a Morning and an Evening odometer reading per day, each with
//   a photo of the odometer + the typed number; the day's distance is the
//   difference (replaced the earlier per-trip Start/End "Rides", which had
//   no data yet, per client spec). All three tables are lazily created on
//   first write (mirrors the o2d_dealers self-healing pattern).
//
// Who gets KM tracking is its own per-user `users.track_km` flag (set from the
// Users page), kept deliberately separate from the free-text `department`
// column — a mechanic's department text can drift/typo without silently
// turning KM tracking on or off for them.
// ══════════════════════════════════════════════════════
async function ensureAttendanceTables() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS attendance (
      id INT AUTO_INCREMENT PRIMARY KEY,
      user_id INT NOT NULL,
      date DATE NOT NULL,
      time_in DATETIME,
      time_out DATETIME,
      lat_in DECIMAL(10,7),
      lng_in DECIMAL(10,7),
      address_in VARCHAR(500),
      lat_out DECIMAL(10,7),
      lng_out DECIMAL(10,7),
      address_out VARCHAR(500),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE KEY uniq_user_date (user_id, date),
      INDEX idx_date (date)
    )
  `);
  await db.query(`
    CREATE TABLE IF NOT EXISTS leave_requests (
      id INT AUTO_INCREMENT PRIMARY KEY,
      user_id INT NOT NULL,
      leave_type VARCHAR(50),
      start_date DATE NOT NULL,
      end_date DATE NOT NULL,
      days DECIMAL(4,1),
      reason TEXT,
      status VARCHAR(20) DEFAULT 'pending',
      approved_by INT,
      approved_at DATETIME,
      remarks TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      INDEX idx_user (user_id),
      INDEX idx_status (status)
    )
  `);
  await db.query(`
    CREATE TABLE IF NOT EXISTS daily_km (
      id INT AUTO_INCREMENT PRIMARY KEY,
      user_id INT NOT NULL,
      date DATE NOT NULL,
      morning_km DECIMAL(10,1),
      morning_photo VARCHAR(1000),
      morning_time DATETIME,
      morning_lat DECIMAL(10,7),
      morning_lng DECIMAL(10,7),
      morning_address VARCHAR(500),
      evening_km DECIMAL(10,1),
      evening_photo VARCHAR(1000),
      evening_time DATETIME,
      evening_lat DECIMAL(10,7),
      evening_lng DECIMAL(10,7),
      evening_address VARCHAR(500),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      UNIQUE KEY uniq_user_date (user_id, date),
      INDEX idx_date (date)
    )
  `);
}
async function withAttendanceTables(fn) {
  try {
    return await fn();
  } catch (e) {
    if (e.code !== 'ER_NO_SUCH_TABLE') throw e;
    await ensureAttendanceTables();
    return await fn();
  }
}

const ATTENDANCE_MIN_SECS_BEFORE_OUT = 120;

// GPS is best-effort — a punch/ride must never fail just because the
// browser denied/lacks location, so lat/lng (and the address text below)
// are simply left null when absent.
function parseCoord(v) {
  if (v == null || v === '') return null;
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : null;
}

// Turns lat/lng into a human-readable address (OpenStreetMap Nominatim —
// free, no API key). Best-effort: a slow/failed lookup just means the row
// keeps its coordinates but no address text; it never blocks the punch/ride.
async function reverseGeocode(lat, lng) {
  if (lat == null || lng == null) return null;
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000);
    const res = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&zoom=16`,
      { headers: { 'User-Agent': 'AjantaTaskManager/1.0 (attendance geocoding)' }, signal: controller.signal }
    );
    clearTimeout(timeoutId);
    if (!res.ok) return null;
    const data = await res.json();
    return data?.display_name ? String(data.display_name).slice(0, 500) : null;
  } catch (e) { return null; }
}

// Punch In/Out must carry a location (client request 2026-10-02 — half the
// punches had none). The address text is retried once and falls back to the
// raw coordinates, so a punch never ends up without a readable location.
const LOCATION_REQUIRED_MSG = 'Location is required to punch — turn on GPS/Location and allow it for this site, then try again.';
async function punchAddress(lat, lng) {
  return (await reverseGeocode(lat, lng)) || (await reverseGeocode(lat, lng)) || `${lat.toFixed(6)}, ${lng.toFixed(6)}`;
}

app.get('/api/attendance/today', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    const [urows] = await db.query('SELECT track_km FROM users WHERE id=?', [uid]);
    const kmTracked = !!(urows[0] && +urows[0].track_km);
    const row = await withAttendanceTables(async () => {
      const [rows] = await db.query('SELECT * FROM attendance WHERE user_id=? AND date=CURDATE()', [uid]);
      return rows[0] || null;
    });
    res.json({ attendance: row, kmTracked });
  } catch (err) { sendServerError(res, err); }
});

app.post('/api/attendance/punch-in', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    const lat = parseCoord(req.body?.lat);
    const lng = parseCoord(req.body?.lng);
    if (lat == null || lng == null) return res.status(400).json({ error: LOCATION_REQUIRED_MSG });
    const address = await punchAddress(lat, lng);
    await withAttendanceTables(async () => {
      const [existing] = await db.query('SELECT id,time_in FROM attendance WHERE user_id=? AND date=CURDATE()', [uid]);
      if (existing[0] && existing[0].time_in) {
        const err = new Error('Already punched in today'); err.code = 'ALREADY_IN'; throw err;
      }
      if (existing[0]) {
        await db.query('UPDATE attendance SET time_in=NOW(), lat_in=?, lng_in=?, address_in=? WHERE id=?', [lat, lng, address, existing[0].id]);
      } else {
        await db.query('INSERT INTO attendance (user_id,date,time_in,lat_in,lng_in,address_in) VALUES (?,CURDATE(),NOW(),?,?,?)', [uid, lat, lng, address]);
      }
    });
    res.json({ success: true });
  } catch (err) {
    if (err.code === 'ALREADY_IN') return res.status(400).json({ error: err.message });
    sendServerError(res, err);
  }
});

app.post('/api/attendance/punch-out', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    const lat = parseCoord(req.body?.lat);
    const lng = parseCoord(req.body?.lng);
    if (lat == null || lng == null) return res.status(400).json({ error: LOCATION_REQUIRED_MSG });
    const address = await punchAddress(lat, lng);
    await withAttendanceTables(async () => {
      const [existing] = await db.query('SELECT id,time_in,time_out,TIMESTAMPDIFF(SECOND,time_in,NOW()) AS secs_since_in FROM attendance WHERE user_id=? AND date=CURDATE()', [uid]);
      if (!existing[0] || !existing[0].time_in) {
        const err = new Error("You haven't punched in yet today"); err.code = 'NOT_IN'; throw err;
      }
      if (existing[0].time_out) {
        const err = new Error('Already punched out today'); err.code = 'ALREADY_OUT'; throw err;
      }
      // The "automatic punch out" reports were really a second tap: right
      // after Punch In the same button turns into Punch Out in the same
      // spot, and live data had punch-outs 7-9s after the punch-in. A real
      // punch-out a couple of minutes after punching in doesn't happen.
      if (Number(existing[0].secs_since_in) < ATTENDANCE_MIN_SECS_BEFORE_OUT) {
        const err = new Error('You just punched in — Punch Out opens after 2 minutes.'); err.code = 'TOO_SOON'; throw err;
      }
      await db.query('UPDATE attendance SET time_out=NOW(), lat_out=?, lng_out=?, address_out=? WHERE id=?', [lat, lng, address, existing[0].id]);
    });
    res.json({ success: true });
  } catch (err) {
    if (err.code === 'NOT_IN' || err.code === 'ALREADY_OUT' || err.code === 'TOO_SOON') return res.status(400).json({ error: err.message });
    sendServerError(res, err);
  }
});

