// ── Not-punched alert — posts the names of staff who haven't punched in
// (and at 8 PM, who haven't punched out) to the team WhatsApp group (same
// group O2D new-order alerts use). Skips holidays, each user's week off /
// extra off, approved leave, and admins. Fired by Vercel cron (vercel.json)
// and, when running as a long-lived server, by the in-process ticker below.
// One send per slot per day — claimed atomically in app_settings so a
// duplicate cron hit / two instances can't post twice.
const ATTENDANCE_ALERT_SLOTS = { morning: 11, evening: 20 }; // IST hour
async function runAttendanceAbsentAlert(slot, { force = false } = {}) {
  if (!ATTENDANCE_ALERT_SLOTS[slot]) throw new Error('Unknown slot');
  const [[clock]] = await db.query(
    "SELECT DATE_FORMAT(CURDATE(),'%Y-%m-%d') AS d, DAYOFWEEK(CURDATE())-1 AS dow, DAYOFMONTH(CURDATE()) AS dom"
  );
  const today = clock.d, dow = Number(clock.dow), nth = Math.ceil(Number(clock.dom) / 7);
  try {
    const [hol] = await db.query('SELECT name FROM holidays WHERE date=?', [today]);
    if (hol.length && !force) return { skipped: `Holiday (${hol[0].name || today})` };
  } catch (e) { if (e.code !== 'ER_NO_SUCH_TABLE') throw e; }

  const [users] = await db.query(
    "SELECT id, name, week_off, extra_off, track_km FROM users WHERE is_active=1 AND (role IS NULL OR role NOT IN ('admin','vendor')) ORDER BY name"
  );
  const working = users.filter(u => {
    const weekOff = String(u.week_off || '').split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
    if (weekOff.includes(dow)) return false;
    let extra = [];
    try { extra = u.extra_off ? JSON.parse(u.extra_off) : []; } catch (_) {}
    return !(Array.isArray(extra) && extra.some(e => e && e.day === dow && Array.isArray(e.weeks) && e.weeks.includes(nth)));
  });
  const [onLeave, attn, kmRows] = await withAttendanceTables(async () => Promise.all([
    db.query("SELECT DISTINCT user_id FROM leave_requests WHERE status='approved' AND ? BETWEEN start_date AND end_date", [today]).then(r => r[0]),
    db.query('SELECT user_id, time_in, time_out FROM attendance WHERE date=?', [today]).then(r => r[0]),
    db.query('SELECT user_id, morning_km, evening_km FROM daily_km WHERE date=?', [today]).then(r => r[0])
  ]));
  const leaveIds = new Set(onLeave.map(r => r.user_id));
  const attnBy = Object.fromEntries(attn.map(a => [a.user_id, a]));
  const expected = working.filter(u => !leaveIds.has(u.id));
  const notIn = expected.filter(u => !(attnBy[u.id] && attnBy[u.id].time_in)).map(u => u.name);
  const notOut = slot === 'evening'
    ? expected.filter(u => attnBy[u.id] && attnBy[u.id].time_in && !attnBy[u.id].time_out).map(u => u.name)
    : [];
  // KM staff (users.track_km) who haven't entered this slot's reading
  // (client, 2026-10-06: KM is paid only on readings entered in the app).
  const kmBy = Object.fromEntries(kmRows.map(k => [k.user_id, k]));
  const kmCol = slot === 'morning' ? 'morning_km' : 'evening_km';
  const noKm = expected.filter(u => +u.track_km && !(kmBy[u.id] && kmBy[u.id][kmCol] != null)).map(u => u.name);
  if (!notIn.length && !notOut.length && !noKm.length) return { skipped: 'Everyone has punched and entered KM', notIn, notOut, noKm };

  const raw = await getAppSetting(O2D_TEAM_GROUP_SETTING);
  const group = raw ? JSON.parse(raw) : null;
  if (!group || !group.id) throw new Error('No team WhatsApp group selected (O2D → 💬 WhatsApp Group)');

  if (!force) {
    await ensureAppSettingsTable();
    const [claim] = await db.query('INSERT IGNORE INTO app_settings (setting_key, setting_value) VALUES (?, ?)',
      [`attn_alert_${slot}_${today}`, new Date().toISOString()]);
    if (!claim.affectedRows) return { skipped: 'Already sent for this slot today' };
  }
  const dmy = today.split('-').reverse().join('/');
  const lines = [`⏰ *Attendance Alert — ${dmy} (${slot === 'morning' ? '11:00 AM' : '8:00 PM'})*`];
  if (notIn.length) lines.push('', `❌ *Punch In nahi kiya (${notIn.length}):*`, ...notIn.map((n, i) => `${i + 1}. ${n}`));
  if (notOut.length) lines.push('', `⚠️ *Punch Out nahi kiya (${notOut.length}):*`, ...notOut.map((n, i) => `${i + 1}. ${n}`));
  if (notIn.length || notOut.length) lines.push('', 'Please punch your attendance in the Ajanta app.');
  if (noKm.length) lines.push('', `⚠️ जिन कर्मचारियों ने अभी तक ऐप पर अपनी ${slot === 'morning' ? 'सुबह की' : 'शाम की'} किलोमीटर रीडिंग नहीं डाली है, उनके नाम नीचे दिए गए हैं।`,
    ...noKm.map((n, i) => `${i + 1}. ${n}`),
    '', 'अब से किलोमीटर का भुगतान केवल ऐप में दर्ज रीडिंग के आधार पर किया जाएगा। कृपया अपनी रीडिंग समय पर ऐप में अपडेट करें।');
  try {
    await sendWhatsApp(group.id, lines.join('\n'));
  } catch (e) {
    // Release the claim so the next tick / a manual retry can send it.
    if (!force) await db.query('DELETE FROM app_settings WHERE setting_key=?', [`attn_alert_${slot}_${today}`]).catch(() => {});
    throw e;
  }
  return { sent: true, notIn, notOut, noKm };
}

// Vercel cron entry point. Vercel sends "Authorization: Bearer <CRON_SECRET>"
// when that env var is set; without it, only Vercel's own cron user agent is
// accepted.
app.get('/api/cron/attendance-alert', async (req, res) => {
  const secret = process.env.CRON_SECRET;
  const ok = secret
    ? req.headers.authorization === `Bearer ${secret}`
    : /vercel-cron/i.test(req.headers['user-agent'] || '');
  if (!ok) return res.status(401).json({ error: 'Unauthorized' });
  try {
    const slot = req.query.slot === 'evening' ? 'evening' : 'morning';
    // Same daily cron also starts the day's Dealer WhatsApp drip messages and
    // nudges any queue that stopped (e.g. the gateway was offline).
    let drips = 0;
    try { if (slot === 'morning') drips = await waEnqueueDueDrips(); waKick(); } catch (e) { console.error('WA drip:', e.message); }
    if (slot === 'morning') try { await collectSendReminders(); } catch (e) { console.error('Payment reminders:', e.message); }
    if (slot === 'morning') try { await deliveryDuesSendReminders(); } catch (e) { console.error('Delivery due reminders:', e.message); }
    res.json({ ...(await runAttendanceAbsentAlert(slot)), drips });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Admin: preview / send now from the Attendance page.
app.post('/api/attendance/absent-alert', requireAuth, requireAdmin, async (req, res) => {
  try {
    const slot = req.body?.slot === 'evening' ? 'evening' : 'morning';
    res.json(await runAttendanceAbsentAlert(slot, { force: true }));
  } catch (err) { if (err.isWhatsApp) return sendWhatsAppError(res, err); res.status(400).json({ error: err.message }); }
});

// Long-lived server (local / non-Vercel): tick every minute, fire each slot
// once its IST hour has arrived (the app_settings claim prevents repeats).
if (!process.env.VERCEL) {
  setInterval(async () => {
    try {
      const [[r]] = await db.query('SELECT HOUR(NOW()) AS h');
      const h = Number(r.h);
      for (const [slot, hour] of Object.entries(ATTENDANCE_ALERT_SLOTS)) {
        if (h >= hour && h < hour + 2) await runAttendanceAbsentAlert(slot);
      }
      if (h >= ATTENDANCE_ALERT_SLOTS.morning) { await waEnqueueDueDrips(); await collectSendReminders().catch(e => console.error('Payment reminders:', e.message)); await ddDailyOnce().catch(e => console.error('Delivery due reminders:', e.message)); }
    } catch (e) { console.error('  ❌ Attendance alert tick:', e.message); }
  }, 60 * 1000).unref();
}

// ── Daily KM — Morning / Evening odometer reading (photo + typed number)
// for KM-tracked (track_km) staff; the day's KM = evening - morning. ──
const KM_PHOTO_MAX_CHARS = 1500000; // ~1MB image after client-side compression

function parseKm(v) {
  if (v == null || v === '') return null;
  const n = parseFloat(v);
  return Number.isFinite(n) && n >= 0 ? Math.round(n * 10) / 10 : null;
}

app.get('/api/km/today', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    const [urows] = await db.query('SELECT track_km FROM users WHERE id=?', [uid]);
    const kmTracked = !!(urows[0] && +urows[0].track_km);
    const row = await withAttendanceTables(async () => {
      const [rows] = await db.query('SELECT * FROM daily_km WHERE user_id=? AND date=CURDATE()', [uid]);
      return rows[0] || null;
    });
    res.json({ km: row, kmTracked });
  } catch (err) { sendServerError(res, err); }
});

// :slot is 'morning' or 'evening' — both need the reading AND an odometer photo.
app.post('/api/km/:slot(morning|evening)', requireAuth, async (req, res) => {
  try {
    const slot = req.params.slot;
    if (slot !== 'morning' && slot !== 'evening') return res.status(400).json({ error: 'Invalid slot' });
    const uid = req.session.userId;
    const km = parseKm(req.body?.km);
    const photo = String(req.body?.photo || '');
    if (km === null) return res.status(400).json({ error: 'Enter the kilometer reading' });
    if (!photo) return res.status(400).json({ error: 'Upload a photo of the kilometer meter' });
    if (photo.length > KM_PHOTO_MAX_CHARS) return res.status(400).json({ error: 'Photo is too large — try again' });

    const existing = await withAttendanceTables(async () => {
      const [rows] = await db.query('SELECT * FROM daily_km WHERE user_id=? AND date=CURDATE()', [uid]);
      return rows[0] || null;
    });
    if (slot === 'morning' && existing && existing.morning_km != null) return res.status(400).json({ error: 'Morning kilometer already saved today' });
    if (slot === 'evening') {
      if (!existing || existing.morning_km == null) return res.status(400).json({ error: 'Save the Morning kilometer first' });
      if (existing.evening_km != null) return res.status(400).json({ error: 'Evening kilometer already saved today' });
      if (km < Number(existing.morning_km)) return res.status(400).json({ error: `Evening reading can't be less than the morning reading (${existing.morning_km})` });
    }

    const lat = parseCoord(req.body?.lat);
    const lng = parseCoord(req.body?.lng);
    const [photoLink, address] = await Promise.all([
      uploadPhotoToDrive(photo, `km-${uid}-${new Date().toISOString().slice(0, 10)}-${slot}.jpg`),
      reverseGeocode(lat, lng)
    ]);
    if (slot === 'morning') {
      await db.query(
        `INSERT INTO daily_km (user_id,date,morning_km,morning_photo,morning_time,morning_lat,morning_lng,morning_address)
         VALUES (?,CURDATE(),?,?,NOW(),?,?,?)
         ON DUPLICATE KEY UPDATE morning_km=VALUES(morning_km), morning_photo=VALUES(morning_photo), morning_time=VALUES(morning_time),
           morning_lat=VALUES(morning_lat), morning_lng=VALUES(morning_lng), morning_address=VALUES(morning_address)`,
        [uid, km, photoLink, lat, lng, address]
      );
    } else {
      await db.query(
        'UPDATE daily_km SET evening_km=?, evening_photo=?, evening_time=NOW(), evening_lat=?, evening_lng=?, evening_address=? WHERE id=?',
        [km, photoLink, lat, lng, address, existing.id]
      );
    }
    res.json({ success: true, dayKm: slot === 'evening' ? Math.round((km - Number(existing.morning_km)) * 10) / 10 : null });
  } catch (err) {
    if (err.code === 403) return res.status(400).json({ error: 'Photo upload failed — the photos Drive is not shared with the service account.' });
    sendServerError(res, err);
  }
});

