// Writes past the sheet's last column fail ("exceeds grid limits"), and
// the Complain FMS tab ended at BK when step 9 was added — widen it (and
// label the new header cells) the first time a write needs to go further.
// Cached per serverless instance once confirmed wide enough.
let _sfmsGridWideEnough = false;
function sfmsLocalLink(v) {
  return String(v || '').replace(/^https?:\/\/[^/]+(\/api\/drive-file\/)/, '$1');
}
async function sfmsEnsureColumns(sheetsApi) {
  if (_sfmsGridWideEnough) return;
  const needed = colToIdx(SFMS_LAST_COL) + 1;
  const meta = await sheetsApi.spreadsheets.get({
    spreadsheetId: SFMS_SHEET_ID, fields: 'sheets(properties(sheetId,title,gridProperties(columnCount)))'
  });
  const tab = meta.data.sheets.find(s => s.properties.title === SFMS_TAB);
  if (!tab) throw new Error(`Tab "${SFMS_TAB}" not found`);
  const have = tab.properties.gridProperties.columnCount;
  if (have < needed) {
    await sheetsApi.spreadsheets.batchUpdate({
      spreadsheetId: SFMS_SHEET_ID,
      requestBody: { requests: [{ appendDimension: { sheetId: tab.properties.sheetId, dimension: 'COLUMNS', length: needed - have } }] }
    });
    const labelData = Object.entries(SFMS_NEW_COLUMN_HEADERS).map(([col, label]) => ({ range: `'${SFMS_TAB}'!${col}${SFMS_HEADER_ROW}`, values: [[label]] }));
    await sheetsApi.spreadsheets.values.batchUpdate({
      spreadsheetId: SFMS_SHEET_ID, requestBody: { valueInputOption: 'RAW', data: labelData }
    });
  }
  _sfmsGridWideEnough = true;
}

// Seasonal-warranty products (client request 2026-09-25): not in Product
// Master, and their warranty isn't N months — it runs to the end of that
// season, i.e. 31 December of the purchase year, whatever month they were
// bought in (bought in November → still covered till 31 Dec). Mirrored in
// app.html's SFMS_SEASONAL_PRODUCTS.
const SFMS_SEASONAL_PRODUCTS = ['Cooler Water Pump', 'Cooler Swing Motor'];
const SFMS_SEASONAL_LOWER = new Set(SFMS_SEASONAL_PRODUCTS.map(n => n.toLowerCase()));

// Warranty expiry Date for a product line, or null when it can't be
// determined (no purchase date / product not in Product Master).
function sfmsWarrantyExpiry(productName, purchaseDate, warrantyMonthsByName) {
  const key = String(productName || '').trim().toLowerCase();
  if (!purchaseDate) return null;
  if (SFMS_SEASONAL_LOWER.has(key)) return new Date(`${purchaseDate.slice(0, 4)}-12-31T23:59:59Z`);
  const months = warrantyMonthsByName[key];
  if (!months) return null;
  const expiry = new Date(purchaseDate + 'T00:00:00Z');
  expiry.setMonth(expiry.getMonth() + months);
  return expiry;
}

function sfmsSerialToDate(n) {
  if (n === '' || n === null || n === undefined) return '';
  if (typeof n !== 'number') return String(n);
  const d = new Date(Date.UTC(1899, 11, 30) + Math.round(n * 86400000));
  return d.toISOString().slice(0, 19).replace('T', ' ');
}
// Inverse of sfmsSerialToDate — write real numeric date-serial values (matching
// how every existing row already stores dates), never date-like strings. A
// plain string here can silently break the sheet's own TIMEVALUE()-based
// automation for "Planned" dates if its format doesn't match the sheet locale.
//
// The sheet has no timezone tag on its numbers — a serial's fractional part
// is just whatever wall-clock hour the business reads it as, which for this
// app is IST. date.getTime() is a UTC instant, so without shifting it first
// every serial we wrote came out 5:30 fast of real IST time (a 4:06pm punch
// recorded as if it were 10:36am) — visibly wrong to anyone reading the
// sheet, and silently wrong for the sheet's own business-hours formulas
// (WORKDAY.INTL/HOUR() checks), which were judging "before 10am"/"after
// 6pm" against the UTC hour instead of the real IST one.
const IST_OFFSET_MS = 5.5 * 60 * 60 * 1000;
function sfmsDateToSerial(date) {
  return (date.getTime() + IST_OFFSET_MS - Date.UTC(1899, 11, 30)) / 86400000;
}

// WhatsApp sending — via the user's own self-hosted "MYAPI" WhatsApp gateway
// (a QR-linked-device session, connected once via MYAPI's own /api/sessions
// flow; not re-established here). Was Maytapi before; kept the same
// mobile-normalizing helper and call shape so nothing else had to change.
// Customer-facing Service FMS WhatsApp texts (client's English formats,
// 2026-10-07 — replaced the Hindi ones of 2026-10-03). Multi-product complaint numbers ("C-56-1") show the shared
// group number ("C-56").
function sfmsDisplayDateTime(d) {
  const ist = new Date(d.getTime() + IST_OFFSET_MS);
  const dd = String(ist.getUTCDate()).padStart(2, '0'), mm = String(ist.getUTCMonth() + 1).padStart(2, '0');
  let h = ist.getUTCHours(); const ampm = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12;
  return `${dd}/${mm}/${ist.getUTCFullYear()} ${h}:${String(ist.getUTCMinutes()).padStart(2, '0')} ${ampm}`;
}
const SFMS_GOOGLE_REVIEW_URL = 'https://share.google/VAuHJcPuwpV8SGWWP';
const SFMS_CUSTOMER_CARE = '8432612777';
function sfmsDearName(name) {
  const n = String(name || '').trim();
  return n ? `Dear ${n}` : 'Dear Customer';
}
function sfmsComplaintRegisteredMsg(name, complainNo, productList, when) {
  return `${sfmsDearName(name)},

Your service complaint has been successfully registered.

Complaint No.: *${complainNo}*
Product : ${productList}
Complaint Date / Time : ${sfmsDisplayDateTime(when)}

Our service team will contact you regarding your complaint and provide the necessary assistance.

For any further assistance, please contact us at:
Customer Care: ${SFMS_CUSTOMER_CARE}

Thank you for choosing *Ajanta Appliances*

Regards,
Team Ajanta Appliances`;
}
function sfmsOtpMsg(name, complainNo, otp) {
  const group = (String(complainNo || '').match(/^(C-\d+)/) || [null, complainNo])[1];
  return `*${sfmsDearName(name)}*,

Your service complaint *${group || ''}* has been successfully resolved.

To confirm the completion of your service, please share the *OTP: ${otp}* with our service technician.

We value your feedback! ⭐
Please take a moment to *rate our service and share your experience on Google.*

👉 *Rate Us on Google:*

${SFMS_GOOGLE_REVIEW_URL}

Thank you for choosing *Ajanta Appliances*

*Regards,*
*Team Ajanta Appliances*`;
}

function sfmsNormalizeMobile(mobile) {
  const digits = String(mobile || '').replace(/\D/g, '');
  const last10 = digits.slice(-10);
  return last10.length === 10 ? `91${last10}` : null;
}

// The gateway's session id is NOT stable — it gets a brand-new id every
// time the linked phone reconnects (confirmed live: the same "Ajanta"
// number came back as a different session id after a routine disconnect/
// reconnect). A fixed MYAPI_SESSION_ID env var would silently go stale and
// break every send until someone noticed, so the connected session is
// looked up live instead, cached briefly to avoid hitting /api/sessions on
// every single message.
let _myapiSessionCache = null; // { id, ts }
const MYAPI_SESSION_CACHE_TTL_MS = 60 * 1000;
// A hard ceiling on every MYAPI call — a plain fetch() has no default
// timeout, and a slow/overloaded gateway (e.g. rate-limited) hanging here
// used to hang the WHOLE request it was called from, including things like
// "Save Order" that only send a WhatsApp alert as a best-effort side
// effect. That surfaced as an HTTP 504 on New Order, not a WhatsApp error.
const MYAPI_TIMEOUT_MS = 10000;
async function myapiConfig() {
  const baseUrl = process.env.MYAPI_BASE_URL;
  const apiKey = process.env.MYAPI_API_KEY;
  if (!baseUrl || !apiKey) throw new Error('WhatsApp (MYAPI) is not configured (missing base URL or API key)');
  const base = baseUrl.replace(/\/$/, '');
  if (!_myapiSessionCache || (Date.now() - _myapiSessionCache.ts) > MYAPI_SESSION_CACHE_TTL_MS) {
    let r;
    try {
      r = await fetch(`${base}/api/sessions`, { headers: { 'X-API-Key': apiKey }, signal: AbortSignal.timeout(MYAPI_TIMEOUT_MS) });
    } catch (e) {
      throw new Error(e.name === 'TimeoutError' || e.name === 'AbortError' ? 'WhatsApp (MYAPI) did not respond in time — the gateway may be overloaded or rate-limited.' : `WhatsApp (MYAPI) unreachable: ${e.message}`);
    }
    const list = await r.json().catch(() => []);
    const sessions = Array.isArray(list) ? list : [];
    const connected = sessions.find(s => s.status === 'connected') || sessions[0];
    if (!connected) throw new Error('WhatsApp (MYAPI) has no session — connect a number in MYAPI first.');
    _myapiSessionCache = { id: connected.id, ts: Date.now() };
  }
  return { base: `${base}/api/sessions/${encodeURIComponent(_myapiSessionCache.id)}`, apiKey };
}

// `mobile` can also be a WhatsApp group id ("1203...@g.us") — MYAPI's
// /send passes those straight through to the group. `media` (optional) is
// MYAPI's own shape: { type: 'image'|'document', url, mimetype?, fileName? }
// — the url must be publicly fetchable by the gateway (e.g. a public Drive
// uc?export=view link from uploadPhotoToDrive(..., { public: true })).
// MYAPI's anti-ban pacing holds a message to a number it hasn't messaged
// before (i.e. almost every customer) for ~4-8s before sending — on purpose —
// so the send itself gets a longer ceiling than the gateway's other calls.
const MYAPI_SEND_TIMEOUT_MS = 30000;
async function sendWhatsApp(mobile, text, media, timeoutMs = MYAPI_SEND_TIMEOUT_MS) {
  const { base, apiKey } = await myapiConfig();
  const raw = String(mobile || '').trim();
  const to = raw.endsWith('@g.us') ? raw : sfmsNormalizeMobile(raw);
  if (!to) throw new Error('Invalid mobile number on file');

  const body = { to, message: text };
  if (media) body.media = media;
  let res;
  try {
    res = await fetch(`${base}/send`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-API-Key': apiKey },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(timeoutMs)
    });
  } catch (e) {
    _myapiSessionCache = null;
    const err = new Error(e.name === 'TimeoutError' || e.name === 'AbortError'
      ? 'WhatsApp (MYAPI) did not respond in time — the gateway may be overloaded or rate-limited.'
      : `WhatsApp (MYAPI) unreachable: ${e.message}`);
    err.isWhatsApp = true;
    throw err;
  }
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data.status === 'error') {
    // Cached session id may just have gone stale (a reconnect since the
    // last lookup) — drop it so the very next send re-resolves fresh
    // instead of failing for up to a minute.
    _myapiSessionCache = null;
    const msg = (data.message || data.error) || `WhatsApp send failed (HTTP ${res.status})`;
    // The gateway's own wording for a dropped linked-device session is
    // cryptic ("Session ... not connected") — say what actually fixes it.
    const err = new Error(/not connected|not active|offline/i.test(msg)
      ? 'WhatsApp is disconnected — re-scan the QR code in MYAPI to reconnect the Ajanta number.'
      : `WhatsApp: ${msg}`);
    err.isWhatsApp = true; // safe to show the user as-is (see sendWhatsAppError)
    throw err;
  }
  return data;
}

// Best-effort WhatsApp alerts are deliberately not awaited (a slow gateway
// mustn't turn Save Order into a 504) — but on Vercel, work still running
// after the response is sent can be frozen mid-flight, silently dropping
// the message. waitUntil keeps the function alive until it settles. This is
// the same lookup @vercel/functions' waitUntil() does; outside Vercel the
// promise simply runs as normal.
function vercelWaitUntil(promise) {
  const ctx = globalThis[Symbol.for('@vercel/request-context')];
  const waitUntil = ctx && typeof ctx.get === 'function' && (ctx.get() || {}).waitUntil;
  if (typeof waitUntil === 'function') waitUntil(promise);
}
// One retry ~8s later: the gateway's linked-device session drops and
// reconnects roughly hourly, and a send landing in that gap used to be lost
// (only ~3 in 10 complaint confirmations arrived). Bad numbers aren't retried.
function sendWhatsAppInBackground(mobile, text, media, label) {
  const p = sendWhatsApp(mobile, text, media)
    .catch(async e => {
      if (/Invalid mobile/i.test(e.message)) throw e;
      console.warn(`WhatsApp (${label}) failed, retrying:`, e.message);
      await new Promise(r => setTimeout(r, 8000));
      return sendWhatsApp(mobile, text, media);
    })
    .catch(e => console.error(`WhatsApp (${label}) failed:`, e.message));
  vercelWaitUntil(p);
  return p;
}

// For sends a person is waiting on (Send OTP, mechanic list): wait only
// briefly. Resolves 'sent' if the gateway finishes within ~3.5s, otherwise
// 'pending' — the send keeps going in the background (waitUntil) instead of
// a spinner sitting through MYAPI's deliberate new-number pacing. A failure
// that comes back quickly (disconnected, bad number) is still thrown.
async function sendWhatsAppQuick(mobile, text, media, label) {
  const p = sendWhatsApp(mobile, text, media);
  vercelWaitUntil(p.catch(e => console.error(`WhatsApp (${label}) failed:`, e.message)));
  const sent = p.then(() => 'sent');
  sent.catch(() => {}); // a failure after the cut-off is logged above, not an unhandled rejection
  const pending = new Promise(resolve => setTimeout(() => resolve('pending'), 3500));
  return Promise.race([sent, pending]);
}

// Like sendServerError, but a failed WhatsApp send's own message is shown
// (it's our own wording, not an internal exception) so staff know to
// reconnect the gateway instead of seeing a generic "Something went wrong".
function sendWhatsAppError(res, err) {
  if (err && (err.isWhatsApp || /MYAPI|mobile number/i.test(err.message || ''))) {
    console.error(err.message);
    return res.status(502).json({ error: err.message });
  }
  sendServerError(res, err);
}

// Best guess at a WhatsApp media type for an uploaded file link — O2D's
// invoice field accepts either a photo or a PDF.
function whatsappMediaFor(url, fileName) {
  const isPdf = /\.pdf$/i.test(fileName || '');
  return isPdf
    ? { type: 'document', url, mimetype: 'application/pdf', fileName }
    : { type: 'image', url };
}

// ── App-wide key/value settings (e.g. the O2D team WhatsApp group id).
// Lazily created on first use, same self-healing pattern as o2d_dealers. ──
async function ensureAppSettingsTable() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS app_settings (
      setting_key VARCHAR(100) PRIMARY KEY,
      setting_value TEXT,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    )
  `);
}
async function getAppSetting(key) {
  try {
    const [rows] = await db.query('SELECT setting_value FROM app_settings WHERE setting_key=?', [key]);
    return rows[0] ? rows[0].setting_value : null;
  } catch (e) {
    if (e.code === 'ER_NO_SUCH_TABLE') return null;
    throw e;
  }
}
async function setAppSetting(key, value) {
  await ensureAppSettingsTable();
  await db.query(
    'INSERT INTO app_settings (setting_key, setting_value) VALUES (?, ?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',
    [key, value]
  );
}

// WhatsApp gateway status + the groups the linked number is in — backs the
// admin "Team WhatsApp Group" picker on the O2D page.
app.get('/api/whatsapp/status', requireAuth, requireAdmin, async (req, res) => {
  try {
    const { base, apiKey } = await myapiConfig();
    const r = await fetch(base, { headers: { 'X-API-Key': apiKey }, signal: AbortSignal.timeout(MYAPI_TIMEOUT_MS) });
    const data = await r.json().catch(() => ({}));
    res.json({ status: data.status || 'unknown', message: data.message || '' });
  } catch (err) { sendServerError(res, err); }
});
app.get('/api/whatsapp/groups', requireAuth, requireAdmin, async (req, res) => {
  try {
    const { base, apiKey } = await myapiConfig();
    const r = await fetch(`${base}/groups`, { headers: { 'X-API-Key': apiKey }, signal: AbortSignal.timeout(MYAPI_TIMEOUT_MS) });
    const data = await r.json().catch(() => ({}));
    if (!r.ok) {
      const msg = data.error || `HTTP ${r.status}`;
      return res.status(400).json({ error: /not connected/i.test(msg) ? 'WhatsApp is disconnected — re-scan the QR code in MYAPI first, then pick the group.' : msg });
    }
    const list = Array.isArray(data) ? data : (data.groups || []);
    res.json(list.map(g => ({ id: g.id || g.jid, name: g.subject || g.name || g.id })).filter(g => g.id));
  } catch (err) { sendServerError(res, err); }
});

