app.put('/api/service-fms/:row/step/:stepNum', requireAuth, async (req, res) => {
  try {
    const row = parseInt(req.params.row, 10);
    const stepNum = parseInt(req.params.stepNum, 10);
    const stepDef = SFMS_STEPS.find(s => s.n === stepNum);
    if (!row || !stepDef) return res.status(400).json({ error: 'Invalid row or step number' });
    const nowVal = sfmsDateToSerial(new Date());
    const sheetsApi = await getSheetsClient(['https://www.googleapis.com/auth/spreadsheets']);
    if (await sfmsRowMoved(res, sheetsApi, row, req.body.expectComplainNo)) return;
    if (!(await sfmsCanActOnRow(req, await sfmsUserAccess(req), stepNum, row, sheetsApi))) return res.status(403).json({ error: 'You are not assigned to this step' });
    let batchData;

    // Spare Check answered "Need to be Purchased" holds the complaint there
    // — no mechanic assignment until the spare is actually in stock.
    if (stepNum === SFMS_N.assign) {
      const s2 = await sheetsApi.spreadsheets.values.get({
        spreadsheetId: SFMS_SHEET_ID, range: `'${SFMS_TAB}'!U${row}:U${row}`
      });
      const spareStatus = (s2.data.values && s2.data.values[0] && s2.data.values[0][0]) || '';
      if (spareStatus !== 'Available') {
        return res.status(400).json({ error: 'Spare is not available yet — mark it "Available" at Spare Check once it has been purchased/added.' });
      }
    }
    // Bill photo is optional at intake (customers often send it later), but
    // a Customer Purchased Piece can't get past Spare Check without it
    // (2026-10-02) — and Takeout keeps the same check for complaints that
    // passed Spare Check before that rule existed.
    if (stepNum === SFMS_N.spareCheck || stepNum === SFMS_N.takeout) {
      const ownAndBill = await sheetsApi.spreadsheets.values.batchGet({
        spreadsheetId: SFMS_SHEET_ID,
        ranges: [`'${SFMS_TAB}'!J${row}:J${row}`, `'${SFMS_TAB}'!${SFMS_OWNERSHIP_COL}${row}:${SFMS_OWNERSHIP_COL}${row}`,
          `'${SFMS_TAB}'!${SFMS_WARRANTY_CHARGES_AGREED_COL}${row}:${SFMS_WARRANTY_CHARGES_AGREED_COL}${row}`]
      });
      const [billRange, ownRange, agreedRange] = ownAndBill.data.valueRanges;
      const noBillAgreed = ((agreedRange.values && agreedRange.values[0] && agreedRange.values[0][0]) || '') === SFMS_NO_BILL_VALUE;
      const hasBill = noBillAgreed || !!(billRange.values && billRange.values[0] && billRange.values[0][0]);
      const ownership = (ownRange.values && ownRange.values[0] && ownRange.values[0][0]) || '';
      if (ownership === 'Customer Purchased Piece' && !hasBill) {
        return res.status(400).json({ error: 'Bill photo is required for a Customer Purchased Piece before it can move past Spare Check — upload it via Edit Complaint first.' });
      }
    }
    if (stepNum === SFMS_N.takeout) {
      let items;
      try { items = JSON.parse(req.body.spareOutJson || '[]'); } catch (e) { items = null; }
      if (!Array.isArray(items) || !items.length) return res.status(400).json({ error: 'Add at least one spare with its quantity' });
      if (items.some(it => !String(it.item || '').trim() || !(Number(it.qty) > 0))) {
        return res.status(400).json({ error: 'Every spare needs a spare name and a quantity of at least 1' });
      }
    }
    if (stepDef.extra.some(e => colToIdx(e.col) > colToIdx('BK')) || colToIdx(stepDef.status) > colToIdx('BK')) {
      await sfmsEnsureColumns(sheetsApi);
    }
    if (stepNum === SFMS_N.inout) return await sfmsHandleInOut(req, res, sheetsApi, row, stepDef, nowVal);

    // Solve: where it was fixed must be picked — the OTP alone used to submit it.
    if (stepNum === SFMS_N.solve && !SFMS_REPAIR_STATUS_VALUES.includes(req.body.repairStatus)) {
      return res.status(400).json({ error: 'Select whether it was repaired at the customer\'s location or the product came to the office' });
    }

    if (stepNum === SFMS_N.solve) {
      const det = sfmsSolveDetails(req.body, await sfmsTakenItems(sheetsApi, row));
      if (det.error) return res.status(400).json({ error: det.error });
      Object.assign(req.body, det.data);
      await sfmsEnsureColumns(sheetsApi);
    }

    // Admin only (client 2026-10-24): complete without the customer's OTP —
    // noted on the record so it is visible who skipped it.
    const adminNoOtp = stepDef.otpRequired && req.session.role === 'admin' && req.body.withoutOtp === true;
    if (adminNoOtp) req.body.workDone = `${req.body.workDone || ''} [Bina OTP — admin ${req.session.name || ''}]`.trim();
    if (stepDef.otpRequired && !adminNoOtp) {
      // A 6-digit code is guessable given enough attempts — cap attempts per
      // row rather than relying on the TTL alone.
      if (isRateLimited(`sfms-otp-verify:${row}`, 8, 15 * 60 * 1000)) {
        return res.status(429).json({ error: 'Too many incorrect attempts — please wait a bit and try again.' });
      }
      const otpRes = await sheetsApi.spreadsheets.values.get({
        spreadsheetId: SFMS_SHEET_ID,
        range: `'${SFMS_TAB}'!${SFMS_OTP_CODE_COL}${row}:${SFMS_OTP_SENT_COL}${row}`
      });
      const otpRow = (otpRes.data.values && otpRes.data.values[0]) || [];
      const storedOtp = otpRow[0] || '';
      const sentAt = otpRow[1] ? new Date(otpRow[1]) : null;
      if (!storedOtp || !sentAt) return res.status(400).json({ error: 'Send the OTP to the customer first' });
      if (Date.now() - sentAt.getTime() > SFMS_OTP_TTL_MS) return res.status(400).json({ error: 'OTP expired — please send a new one' });
      if (String(req.body.otp || '').trim() !== String(storedOtp).trim()) return res.status(400).json({ error: 'Incorrect OTP' });
    }

    if (stepDef.twoStage) {
      const stage = req.body.stage;
      if (stage === 'out') {
        batchData = [{ range: `'${SFMS_TAB}'!${stepDef.out}${row}`, values: [[nowVal]] }];
        for (const e of stepDef.extra) {
          if (e.stage === 'out' && req.body[e.key] !== undefined && req.body[e.key] !== '') {
            batchData.push({ range: `'${SFMS_TAB}'!${e.col}${row}`, values: [[req.body[e.key]]] });
          }
        }
      } else if (stage === 'in') {
        batchData = [
          { range: `'${SFMS_TAB}'!${stepDef.in}${row}`, values: [[nowVal]] },
          { range: `'${SFMS_TAB}'!${stepDef.status}${row}`, values: [['Yes']] }
        ];
        for (const e of stepDef.extra) {
          if (e.stage === 'in' && req.body[e.key] !== undefined && req.body[e.key] !== '') {
            batchData.push({ range: `'${SFMS_TAB}'!${e.col}${row}`, values: [[req.body[e.key]]] });
          }
        }
      } else {
        return res.status(400).json({ error: "stage must be 'out' or 'in' for this step" });
      }
    } else {
      // status defaults to 'Yes' for plain completion steps; steps with a dropdown
      // answer (warranty Yes/No, spare Available/Need to Purchase, Complaint Solved
      // Yes/No) send their actual selected value instead.
      batchData = [
        { range: `'${SFMS_TAB}'!${stepDef.actual}${row}`, values: [[nowVal]] },
        { range: `'${SFMS_TAB}'!${stepDef.status}${row}`, values: [[req.body.status || 'Yes']] }
      ];
      for (const e of stepDef.extra) {
        if (req.body[e.key] !== undefined && req.body[e.key] !== '') {
          batchData.push({ range: `'${SFMS_TAB}'!${e.col}${row}`, values: [[req.body[e.key]]] });
        }
      }
      if (stepDef.otpRequired) {
        // One-time use — clear so the same OTP can't be replayed.
        batchData.push({ range: `'${SFMS_TAB}'!${SFMS_OTP_CODE_COL}${row}:${SFMS_OTP_SENT_COL}${row}`, values: [['', '']] });
      }
    }

    await sheetsApi.spreadsheets.values.batchUpdate({
      spreadsheetId: SFMS_SHEET_ID,
      requestBody: { valueInputOption: 'USER_ENTERED', data: batchData }
    });

    res.json({ success: true });
  } catch (err) {
    if (err.code === 403) return res.status(400).json({ error: 'Access denied — please share the sheet with the service account.' });
    sendServerError(res, err);
  }
});

// ══════════════════════════════════════════════════════
// O2D FMS — live-connected to the real "Order To Dispatch Fms" Google
// Sheet (tab "Master." — trailing dot; this is the customer's own
// production sheet, not our app's Google Sheet DB). The sheet also has a
// "Master" tab (no dot) with a fuller 21-step layout, but its data shows
// ~92% of orders never progressing past step 1 — it's a stalled/unused
// redesign. "Master." is the one actually driving the business: 77% of
// its orders (1803/2341) run all the way through step 9.
//
// Columns were verified two ways: reading the header row directly, and
// (because the header disagreed with itself for step 9 — its own labels
// call BE "Status" and BF "Loader Name") sampling hundreds of real data
// rows per column to see which one actually holds Yes/No values versus
// names. BF holds "Yes"/"No" and BE holds names — the header is wrong,
// the mapping below follows the data.
// ══════════════════════════════════════════════════════
// "Order To Dispatch Fms Erp" — this replaced the old '1pWxyrbDF...' workbook.
// Master. used to be a QUERY(IMPORTRANGE(...)) pulling live from a separate
// intake spreadsheet; that formula has been flattened to static values so
// this sheet is now self-contained (New Order appends straight into it, no
// other spreadsheet involved).
const O2D_SHEET_ID = '1UWGXIuB4Igl4siTzbSP9RmtV5EcnubkW2-MJtMu4lbY';
const O2D_TAB = 'Master.';
const O2D_HEADER_ROW = 6;
const O2D_DATA_START_ROW = 7;
const O2D_LAST_COL = 'BM';

// doer + tat (the "Who"/"When" rows in Master.'s own header, rows 3 & 5)
const O2D_STEPS = [
  { n: 1, label: 'Accounts is ok or not', doer: 'Accountant', tat: '10 min', planned: 'T', actual: 'U', status: 'V',
    extra: [ { key: 'reason', col: 'W', label: 'Reason' } ] },
  { n: 2, label: 'Good Check', doer: 'Niranjan (Warehouse Manager)', tat: '10 min', planned: 'X', actual: 'Y', status: 'Z', timeDelay: 'AA', extra: [] },
  { n: 3, label: 'Call Made By CRM When Add More Order', doer: 'Kavita', tat: '10 min', planned: 'AB', actual: 'AC', status: 'AD', timeDelay: 'AE', extra: [] },
  { n: 4, label: 'Make Bill', doer: 'Accountant', tat: '10 min', planned: 'AF', actual: 'AG', status: 'AH', timeDelay: 'AI',
    // Bill detail columns live far from this step's own Planned/Actual/Status
    // block, at the very end of the sheet (BJ:BM) — everything else here
    // reads BJ/BK for display already; this is what actually WRITES them.
    extra: [
      { key: 'billNo', col: 'BJ', label: 'Bill No' },
      { key: 'billAmount', col: 'BK', label: 'Bill Amount' },
      { key: 'photoLink', col: 'BL', label: 'Invoice Photo' },
      { key: 'billDate', col: 'BM', label: 'Bill Date', isDate: true }
    ] },
  { n: 5, label: 'Goods Takeout and Photo', doer: 'Niranjan (Warehouse Manager)', tat: '30 min', planned: 'AJ', actual: 'AK', status: 'AL', timeDelay: 'AO',
    extra: [
      { key: 'doerName', col: 'AM', label: 'Doer Name' },
      { key: 'photo', col: 'AN', label: 'Photo (link)' }
    ] },
  { n: 6, label: 'Check physical stock with bill', doer: 'Aziz', tat: '10 min', planned: 'AP', actual: 'AQ', status: 'AR', timeDelay: 'AT',
    extra: [ { key: 'doerName', col: 'AS', label: 'Doer Name' } ] },
  { n: 7, label: 'Arrange Loader', doer: 'Kavita', tat: '10 min', planned: 'AU', actual: 'AV', status: 'AW', timeDelay: 'AX', extra: [] },
  { n: 8, label: 'In/ Out Entry', doer: 'Priyanka (SCCRR)', tat: '10 min', planned: 'AY', actual: 'AZ', status: 'BA', timeDelay: 'BB', extra: [] },
  { n: 9, label: 'Load Goods', doer: 'Niranjan (Warehouse Manager)', tat: '30 min', planned: 'BC', actual: 'BD', status: 'BE', timeDelay: 'BG',
    extra: [
      { key: 'loaderName', col: 'BF', label: 'Doer Name' },
      { key: 'deliveryBy', col: 'BI', label: 'Delivery By' }
    ] }
];

// ── O2D step doers — who's actually assigned to each of the 9 fixed steps.
// O2D_STEPS' own `doer` field is just a static role label ("Accountant",
// "Kavita"...); this layers real user assignments on top, same shape as the
// generic FMS system's fms_step_doers table.
async function ensureO2dStepDoersTable() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS o2d_step_doers (
      step_n INT NOT NULL,
      user_id INT NOT NULL,
      PRIMARY KEY (step_n, user_id)
    )
  `);
}
async function withO2dStepDoersTable(fn) {
  try { return await fn(); }
  catch (e) { if (e.code !== 'ER_NO_SUCH_TABLE') throw e; await ensureO2dStepDoersTable(); return await fn(); }
}

let _o2dStepDoersCache = null; // { map, ts } — step_n -> [{id,name}]
const O2D_STEP_DOERS_CACHE_TTL_MS = 60 * 1000;
async function getO2dStepDoersMap() {
  if (_o2dStepDoersCache && (Date.now() - _o2dStepDoersCache.ts) < O2D_STEP_DOERS_CACHE_TTL_MS) return _o2dStepDoersCache.map;
  const [rows] = await withO2dStepDoersTable(() => db.query(
    `SELECT osd.step_n, u.id, u.name FROM o2d_step_doers osd JOIN users u ON osd.user_id=u.id ORDER BY u.name`
  ));
  const map = {};
  rows.forEach(r => { (map[r.step_n] = map[r.step_n] || []).push({ id: r.id, name: r.name }); });
  _o2dStepDoersCache = { map, ts: Date.now() };
  return map;
}

app.get('/api/o2d-fms/step-doers', requireAuth, async (req, res) => {
  try {
    const map = await getO2dStepDoersMap();
    const assignments = {};
    O2D_STEPS.forEach(s => { assignments[s.n] = map[s.n] || []; });
    res.json({ assignments });
  } catch (err) { sendServerError(res, err); }
});

app.put('/api/o2d-fms/step-doers', requireAuth, requireAdmin, async (req, res) => {
  try {
    const { assignments } = req.body; // { "1": [userId,...], "2": [...], ... }
    await ensureO2dStepDoersTable();
    await db.query('DELETE FROM o2d_step_doers');
    const rows = [];
    Object.entries(assignments || {}).forEach(([stepN, userIds]) => {
      (userIds || []).forEach(uid => rows.push([Number(stepN), Number(uid)]));
    });
    if (rows.length) await db.query('INSERT INTO o2d_step_doers (step_n, user_id) VALUES ?', [rows]);
    _o2dStepDoersCache = null;
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

// Sheet read is cached by version (see cachedBySheetVer near the top) — every
// write under /api/o2d-fms bumps it. Cloned: callers and the extras below
// mutate orders.
async function getO2dOrders() {
  const orders = await cachedBySheetVer('o2d', readO2dOrdersFromSheet, true);

  // Hold / app-side Cancel / dispatch videos (o2d_order_flags, o2d_media).
  let extras = { flagBy: {}, mediaBy: {} };
  try { extras = await getO2dOrderExtras(); } catch (e) { console.error('O2D extras:', e.message); }
  orders.forEach(o => {
    const f = extras.flagBy[o.orderNo];
    o.videos = extras.mediaBy[o.orderNo] || [];
    if (!f) return;
    o.restartCount = f.restart_count || 0;
    // Shown on the Dashboard row — a restarted order comes back to every step's doer (client list 10-26 #4).
    if (o.restartCount && f.restarted_at) Object.assign(o, { restartedBy: f.restarted_by || '', restartedAt: f.restarted_at });
    if (f.carried_by) Object.assign(o, { carriedBy: f.carried_by, carriedSetBy: f.carried_set_by || '' });
    if (f.cancelled && !o.closed) { o.cancelled = true; o.closed = true; o.cancelledStepLabel = o.cancelledStepLabel || 'Cancelled'; }
    if (f.cancelled) Object.assign(o, { cancelReason: f.cancel_reason || '', cancelledBy: f.cancelled_by || '', cancelledAt: f.cancelled_at || '' });
    if (f.on_hold && !o.closed) Object.assign(o, { onHold: true, holdType: f.hold_type || 'other', holdReason: f.hold_reason || '', holdBy: f.hold_by || '', holdAt: f.hold_at || '' });
  });

  orders.reverse(); // newest first
  return orders;
}

async function readO2dOrdersFromSheet() {
  {
    const stepDoersMap = await getO2dStepDoersMap();
    const sheetsApi = await getSheetsClient(['https://www.googleapis.com/auth/spreadsheets.readonly']);
    let result;
    for (let attempt = 0; ; attempt++) {
      try {
        result = await sheetsApi.spreadsheets.values.get({
          spreadsheetId: O2D_SHEET_ID,
          range: `'${O2D_TAB}'!A${O2D_DATA_START_ROW}:${O2D_LAST_COL}`,
          valueRenderOption: 'UNFORMATTED_VALUE'
        });
        break;
      } catch (e) {
        const isRateLimit = e.code === 429 || (e.message || '').includes('Quota exceeded');
        if (!isRateLimit || attempt >= 2) throw e;
        await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
      }
    }
    const sheetRows = result.data.values || [];
    const lines = sheetRows.map((r, i) => {
      const rowNum = O2D_DATA_START_ROW + i;
      const get = col => r[colToIdx(col)];
      if (!get('R')) return null; // skip blank rows (Order Id is the unique key column)
      const line = {
        row: rowNum,
        timestamp: sfmsSerialToDate(get('A')),
        counterType: get('B') || '',
        counterName: get('C') || '',
        area: get('D') || '',
        dateToSend: get('E') ? sfmsSerialToDate(get('E')).split(' ')[0] : '',
        whenToSend: get('F') || '',
        channel: get('G') || '',
        deliverByTransport: get('H') || '',
        makePerformaInvoice: get('I') || '',
        orderBy: get('J') || '',
        paymentTerms: get('K') || '',
        remark: get('L') || '',
        productName: get('M') || '',
        rate: get('N') || '',
        qty: get('O') || '',
        isSample: get('P') || '',
        orderNo: get('Q') || '',
        orderId: get('R') || '',
        billNo: get('BJ') || '',
        amount: get('BK') || ''
      };
      line.steps = O2D_STEPS.map(sd => {
        const step = {
          planned: sd.planned ? sfmsSerialToDate(get(sd.planned)) : '',
          actual: sd.actual ? sfmsSerialToDate(get(sd.actual)) : '',
          status: get(sd.status) || ''
        };
        sd.extra.forEach(e => {
          const val = get(e.col);
          step[e.key] = e.isDate && typeof val === 'number' ? sfmsSerialToDate(val).split(' ')[0] : (val || '');
        });
        return step;
      });
      // A "No" answer (e.g. Accounts not ok, item Not Available) ends the
      // line right there — it doesn't count as clearing the step, and
      // nothing past it is expected to happen (see o.cancelled below).
      // cancelledStepLabel is exposed per-line (not just per-order) so
      // reports can say WHY a specific item was lost — Good Check for a
      // per-item "Not Available", or whichever order-level step actually
      // failed.
      let lineCurrentStep = 0, lineCancelled = false, lineCancelledStepLabel = '';
      for (let i = 0; i < line.steps.length; i++) {
        const s = line.steps[i];
        if (s.status === 'No') { lineCancelled = true; lineCancelledStepLabel = O2D_STEPS[i].label; break; }
        if (s.status) lineCurrentStep++; else break;
      }
      line.currentStep = lineCurrentStep;
      line.cancelled = lineCancelled;
      line.cancelledStepLabel = lineCancelledStepLabel;
      return line;
    }).filter(Boolean);

    // One order = one Order No., not one product row. A step is only
    // "done" for the order once every one of its product lines has it, and
    // the order's currentStep is bottlenecked by whichever line is furthest
    // behind — so a freshly added item (Add Order, step 3) correctly drags
    // the whole order back to "pending" on the steps it hasn't cleared,
    // while lines that already finished those steps keep their own data.
    const orderNos = [];
    const byOrderNo = {};
    lines.forEach(line => {
      if (!byOrderNo[line.orderNo]) { byOrderNo[line.orderNo] = []; orderNos.push(line.orderNo); }
      byOrderNo[line.orderNo].push(line);
    });

    const orders = orderNos.map(orderNo => {
      const group = byOrderNo[orderNo];
      const first = group[0];
      const o = {
        orderNo,
        rows: group.map(l => l.row),
        timestamp: group.map(l => l.timestamp).sort()[0],
        counterType: first.counterType,
        counterName: first.counterName,
        area: first.area,
        dateToSend: first.dateToSend,
        whenToSend: first.whenToSend,
        channel: first.channel,
        deliverByTransport: first.deliverByTransport,
        makePerformaInvoice: first.makePerformaInvoice,
        orderBy: first.orderBy,
        paymentTerms: first.paymentTerms,
        remark: first.remark,
        billNo: first.billNo,
        // Bill Amount is an order-level value the Accountant enters once (see
        // writeO2dStepForOrder) but gets written identically onto every
        // product-line row sharing this Order No — summing it across the
        // group was multiplying a 2-product order's real amount by 2x, a
        // 3-product order by 3x, etc. Every row in the group has the same
        // value, so just take one.
        amount: Number(first.amount) || 0,
        productName: group.length > 1 ? `${first.productName} +${group.length - 1} more` : first.productName,
        qty: group.reduce((sum, l) => sum + (Number(l.qty) || 0), 0),
        // availability = the raw Good Check (step 2) status for this line —
        // 'Yes'/'No'/'' — kept per product so other steps can show what was
        // picked instead of asking the per-item question again. cancelled
        // mirrors line.cancelled — this ONE item is done/excluded, not the
        // whole order (see the order-level cancel logic below).
        products: group.map(l => ({ row: l.row, orderId: l.orderId, productName: l.productName, rate: l.rate, qty: l.qty, isSample: l.isSample, currentStep: l.currentStep, cancelled: l.cancelled, cancelledStepLabel: l.cancelledStepLabel, availability: (l.steps[1] && l.steps[1].status) || '' }))
      };
      o.steps = O2D_STEPS.map((sd, idx) => {
        const lineSteps = group.map(l => l.steps[idx]);
        const allDone = lineSteps.every(s => s.status);
        const actuals = lineSteps.map(s => s.actual).filter(Boolean).sort();
        const step = {
          n: sd.n, label: sd.label, doer: sd.doer, tat: sd.tat, doers: stepDoersMap[sd.n] || [],
          planned: lineSteps[0].planned,
          actual: allDone ? (actuals[actuals.length - 1] || '') : '',
          // Order-level steps (e.g. Accounts Yes/No) write the SAME status
          // to every line, so this preserves the real answer. Only Good
          // Check (per-item) can legitimately have lines that disagree —
          // some items available, some not, which is normal, not a whole-
          // order "No" — so a mix there just shows "Yes" (done); the real
          // per-item picture lives in each product's own `availability`,
          // and the cancel/continue decision below is made from each
          // line's own data, not this aggregate.
          status: allDone ? (lineSteps.every(s => s.status === lineSteps[0].status) ? lineSteps[0].status : 'Yes') : ''
        };
        sd.extra.forEach(e => {
          const withVal = lineSteps.find(s => s[e.key]);
          step[e.key] = withVal ? withVal[e.key] : '';
        });
        return step;
      });
      // The order's progress is bottlenecked by whichever of its STILL-
      // ACTIVE lines is furthest behind — a line "Not Available" at Good
      // Check (per-item, step index 1) is finished on its own and
      // shouldn't hold back other items that ARE available. Only when
      // every line ends up cancelled (nothing left to deliver at all)
      // does the whole order count as cancelled. A "No" on any OTHER step
      // still ends the whole order immediately — those write one shared
      // answer for every line (not a per-item one), so if any line
      // stopped there, they all did.
      const GOOD_CHECK_IDX = 1;
      const activeLines = group.filter(l => !l.cancelled);
      const orderLevelCancel = group.find(l => l.cancelled && l.currentStep !== GOOD_CHECK_IDX);
      let currentStep, cancelled = false, cancelledStepLabel = '';
      if (orderLevelCancel) {
        cancelled = true;
        currentStep = orderLevelCancel.currentStep;
        cancelledStepLabel = O2D_STEPS[currentStep].label;
      } else if (!activeLines.length) {
        cancelled = true;
        currentStep = GOOD_CHECK_IDX;
        cancelledStepLabel = O2D_STEPS[GOOD_CHECK_IDX].label;
      } else {
        currentStep = Math.min(...activeLines.map(l => l.currentStep));
      }
      o.currentStep = currentStep;
      o.cancelled = cancelled;
      o.cancelledStepLabel = cancelledStepLabel;
      o.closed = cancelled || currentStep === O2D_STEPS.length;
      return o;
    });

    return orders;
  }
}

app.get('/api/o2d-fms', requireAuth, async (req, res) => {
  try {
    res.json(await getO2dOrders());
  } catch (err) {
    if (err.code === 403) return res.status(400).json({ error: 'Access denied — please share the sheet with the service account.' });
    sendServerError(res, err);
  }
});

// ── New Order ── used to append to a separate intake spreadsheet that fed
// Master. via IMPORTRANGE; that formula is now flattened to static values
// (see O2D_SHEET_ID comment above), so new orders append straight into
// Master. itself — no other spreadsheet involved, and no import lag.

// ── Customer outstanding lookup (Tally debtors report sheet) ──
// Sheet has just [Party Name, Debit/Outstanding] rows — no credit limit column.
const O2D_DEBTORS_SHEET_ID = '1oCGFCvCwuZRLHa_OV3Ae9PMjiaBr9VpAxCi3uMjqb-k';
const O2D_DEBTORS_TAB = 'Sheet1';
let _debtorsCache = null; // { map, ts }
const DEBTORS_CACHE_TTL_MS = 10 * 60 * 1000; // sheet is a daily Tally export, no need to re-read often

async function getDebtorsMap() {
  if (_debtorsCache && (Date.now() - _debtorsCache.ts) < DEBTORS_CACHE_TTL_MS) return _debtorsCache.map;
  try {
    const sheetsApi = await getSheetsClient(['https://www.googleapis.com/auth/spreadsheets.readonly']);
    let resp;
    for (let attempt = 0; ; attempt++) {
      try {
        resp = await sheetsApi.spreadsheets.values.get({
          spreadsheetId: O2D_DEBTORS_SHEET_ID,
          range: `${O2D_DEBTORS_TAB}!A1:B1000`
        });
        break;
      } catch (e) {
        const isRateLimit = e.code === 429 || (e.message || '').includes('Quota exceeded');
        if (!isRateLimit || attempt >= 2) throw e;
        await new Promise(r => setTimeout(r, 2000 * (attempt + 1)));
      }
    }
    const rows = resp.data.values || [];
    const map = {};
    let started = false; // rows before the ["", "Debit", "Credit"] header are report title/metadata, not data
    for (const row of rows) {
      if (!started) {
        if (row[1] === 'Debit') started = true;
        continue;
      }
      const name = (row[0] || '').trim();
      if (!name || name === 'Grand Total') continue;
      const num = parseFloat(String(row[1] || '').replace(/,/g, ''));
      if (!isNaN(num)) map[name.toLowerCase()] = { name, outstanding: num };
    }
    _debtorsCache = { map, ts: Date.now() };
    return map;
  } catch (e) {
    // Sheets API hiccup (rate limit etc.) — serve stale cache rather than failing outright, if we have one
    if (_debtorsCache) return _debtorsCache.map;
    throw e;
  }
}

app.get('/api/o2d-fms/customer-lookup', requireAuth, async (req, res) => {
  try {
    const q = (req.query.name || '').trim().toLowerCase();
    if (!q) return res.json({ found: false });
    const map = await getDebtorsMap();
    if (map[q]) return res.json({ found: true, ...map[q] });
    const match = Object.values(map).find(v => v.name.toLowerCase().includes(q) || q.includes(v.name.toLowerCase()));
    if (match) return res.json({ found: true, ...match, fuzzy: true });
    res.json({ found: false });
  } catch (err) { sendServerError(res, err); }
});

app.get('/api/o2d-fms/customer-names', requireAuth, async (req, res) => {
  try {
    const map = await getDebtorsMap();
    const names = Object.values(map).map(v => v.name).sort((a, b) => a.localeCompare(b));
    res.json({ names });
  } catch (err) { sendServerError(res, err); }
});

// ══════════════════════════════════════════════════════
// O2D DEALERS — profile (city/phone/credit limit/location/KYC) +
// payment-history rating, layered on top of the debtors sheet and
// the live order data. Both tables are lazily created on first write
// (mirrors the week_plans/app_settings self-healing pattern).
// ══════════════════════════════════════════════════════
async function ensureDealerTables() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS o2d_dealers (
      id INT AUTO_INCREMENT PRIMARY KEY,
      counter_name VARCHAR(255) NOT NULL UNIQUE,
      city VARCHAR(255),
      phone VARCHAR(50),
      credit_limit DECIMAL(12,2),
      location_lat DECIMAL(10,7),
      location_lng DECIMAL(10,7),
      location_address VARCHAR(500),
      kyc_aadhar_url VARCHAR(1000),
      kyc_pan_url VARCHAR(1000),
      kyc_gst_url VARCHAR(1000),
      kyc_shop_url VARCHAR(1000),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    )
  `);
  await db.query(`
    CREATE TABLE IF NOT EXISTS o2d_dealer_payments (
      id INT AUTO_INCREMENT PRIMARY KEY,
      counter_name VARCHAR(255) NOT NULL,
      amount DECIMAL(12,2),
      due_date DATE,
      paid_date DATE,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      INDEX idx_counter (counter_name)
    )
  `);
}

async function withDealerTables(fn) {
  try {
    if (!_dealerDetailColsOk) await ensureDealerDetailCols();
    return await fn();
  } catch (e) {
    if (e.code !== 'ER_NO_SUCH_TABLE') throw e;
    await ensureDealerTables();
    await ensureDealerDetailCols();
    return await fn();
  }
}
// Dealer's own details, kept up to date by the salesman on each market visit
// (client, 2026-10-09: "jaisa employees ka banaya hai, aisa hi dealer ka" —
// owner, date of birth, address, location…). Same one dealer list, O2D → Dealers.
const DEALER_DETAIL_COLS = [['owner_name', 'VARCHAR(255)'], ['alt_phone', 'VARCHAR(50)'], ['area', 'VARCHAR(255)'], ['address', 'VARCHAR(1000)'],
  ['dob', 'DATE'], ['anniversary', 'DATE'], ['gst_no', 'VARCHAR(30)'], ['notes', 'VARCHAR(1000)'], ['details_updated_by', 'INT'], ['details_updated_at', 'DATETIME'],
  // credit_days: payment terms; tally_name: the party's name in Tally when it is written differently
  ['credit_days', 'INT'], ['tally_name', 'VARCHAR(255)'],
  // bilty: a sample bilty photo of an outstation dealer, so everyone knows which transport his goods go by (client 2026-10-24)
  ['bilty_url', 'VARCHAR(1000)'], ['bilty_transport', 'VARCHAR(255)'], ['bilty_updated_at', 'DATETIME'],
  // hidden_at: admin deleted the dealer from the list (client list 2026-10-26 #3) — a later O2D order brings him back
  ['hidden_at', 'DATETIME'], ['hidden_by', 'INT']];
let _dealerDetailColsOk = false;
async function ensureDealerDetailCols() {
  await addMissingColumns('o2d_dealers', DEALER_DETAIL_COLS);
  _dealerDetailColsOk = true;
}

// Tally dates come back as "DD-Mon-YY" / "DD-Mon-YYYY" (e.g. "29-Mar-16") —
// convert to a real Date so it can be compared/subtracted properly.
const TALLY_MONTHS = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
function parseTallyDate(str) {
  const m = String(str || '').trim().match(/^(\d{1,2})-([A-Za-z]{3})-(\d{2,4})$/);
  if (!m) return null;
  const month = TALLY_MONTHS[m[2].toLowerCase()];
  if (month === undefined) return null;
  let year = parseInt(m[3], 10);
  if (year < 100) year += year < 50 ? 2000 : 1900;
  const d = new Date(year, month, parseInt(m[1], 10));
  return isNaN(d.getTime()) ? null : d;
}
function toIsoDate(d) { return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; }
// A handful of older synced rows can still carry a plain "YYYY-MM-DD" date
// instead of Tally's own "DD-Mon-YY" — leftover from before the sync
// switched its sheet writes from USER_ENTERED to RAW (USER_ENTERED let
// Sheets auto-convert some date-shaped strings but not others, inconsistently).
function parseAnyDate(str) {
  const tally = parseTallyDate(str);
  if (tally) return tally;
  const m = String(str || '').trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const d = new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, parseInt(m[3], 10));
  return isNaN(d.getTime()) ? null : d;
}

function computeDealerRating(payments) {
  if (!payments.length) return { stars: 0, label: null, total: 0, late: 0, avgLateDays: 0 };
  let late = 0, lateDaysSum = 0;
  for (const p of payments) {
    if (p.due_date && p.paid_date && p.paid_date > p.due_date) {
      late++;
      lateDaysSum += Math.round((new Date(p.paid_date) - new Date(p.due_date)) / 86400000);
    }
  }
  const total = payments.length;
  const onTimeRatio = (total - late) / total;
  const stars = Math.max(1, Math.round(onTimeRatio * 5));
  const label = stars >= 4 ? 'Good' : stars === 3 ? 'OK' : 'Risky';
  return { stars, label, total, late, avgLateDays: late > 0 ? Math.round(lateDaysSum / late) : 0 };
}

// Dealer directory lives under the same page as O2D FMS in the UI — admins
// always have it, everyone else needs 'o2d-fms' explicitly granted, same
// gate the Dealers tab itself lives behind. Previously these routes only
// checked the caller was logged in at all, exposing every dealer's credit
// limit, payment ledger and KYC document links to any employee.
async function canAccessDealers(req) {
  if (req.session.role === 'admin') return true;
  const [rows] = await db.query('SELECT page_access FROM users WHERE id=?', [req.session.userId]);
  const pages = parsePageAccess(rows[0] ? rows[0].page_access : null, req.session.role);
  // 'dealers' = Dealer Master page grant; O2D FMS still reads dealer data for its own screens.
  return pages.includes('dealers') || pages.includes('o2d-fms');
}
// Credit limit and payment history directly feed the automated credit-tier
// rating (computeCreditTier/computeDealerRating) — restrict those to admin
// only, distinct from the more permissive view/KYC/location actions above.
function canEditDealers(req) {
  return req.session.role === 'admin';
}

// Admin fixes a wrongly typed dealer name. Old orders in the sheet keep the old
// name, so it is kept as an alias that folds into the new one everywhere the
// Dealer list merges by name; the app's own tables move to the new name.
async function getDealerAliasMap() {
  try {
    const [rows] = await db.query('SELECT alias_key, counter_name FROM o2d_dealer_aliases');
    return Object.fromEntries(rows.map(r => [r.alias_key, r.counter_name]));
  } catch (e) { if (e.code === 'ER_NO_SUCH_TABLE') return {}; throw e; }
}
app.put('/api/o2d-fms/dealers/:name/rename', requireAuth, async (req, res) => {
  try {
    if (!canEditDealers(req)) return res.status(403).json({ error: 'Dealer ka naam sirf Admin badal sakta hai' });
    const oldName = String(req.params.name || '').trim();
    const newName = String((req.body || {}).newName || '').trim().slice(0, 255);
    if (!oldName || !newName) return res.status(400).json({ error: 'Naya naam likhein' });
    if (oldName === newName) return res.json({ success: true });
    await db.query(`CREATE TABLE IF NOT EXISTS o2d_dealer_aliases (alias_key VARCHAR(191) PRIMARY KEY, counter_name VARCHAR(255) NOT NULL,
      created_by INT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4`);
    const [[clash]] = await withDealerTables(() => db.query('SELECT counter_name FROM o2d_dealers WHERE LOWER(counter_name)=LOWER(?) AND LOWER(counter_name)<>LOWER(?)', [newName, oldName]));
    if (clash) return res.status(400).json({ error: `"${clash.counter_name}" naam ka dealer pehle se hai` });
    // One transaction: a failure half-way must not leave the dealer renamed
    // in some tables and not others.
    await withTx(async conn => {
      const [[row]] = await conn.query('SELECT counter_name FROM o2d_dealers WHERE LOWER(counter_name)=LOWER(?)', [oldName]);
      if (row) await conn.query('UPDATE o2d_dealers SET counter_name=? WHERE counter_name=?', [newName, row.counter_name]);
      else await conn.query('INSERT INTO o2d_dealers (counter_name) VALUES (?)', [newName]);
      const move = async (sql, params) => { try { await conn.query(sql, params); } catch (e) { if (e.code !== 'ER_NO_SUCH_TABLE') throw e; } };
      await move('UPDATE o2d_dealer_payments SET counter_name=? WHERE LOWER(counter_name)=LOWER(?)', [newName, oldName]);
      await move('UPDATE sales_counters SET counter_name=? WHERE LOWER(counter_name)=LOWER(?)', [newName, oldName]);
      await move('UPDATE sales_schedule SET dealer_name=? WHERE LOWER(dealer_name)=LOWER(?)', [newName, oldName]);
      await move('UPDATE dealer_onboardings SET shop_name=? WHERE LOWER(shop_name)=LOWER(?)', [newName, oldName]);
      // Old name (and anything that already pointed to it) now means the new one.
      await conn.query('UPDATE o2d_dealer_aliases SET counter_name=? WHERE LOWER(counter_name)=LOWER(?)', [newName, oldName]);
      await conn.query('DELETE FROM o2d_dealer_aliases WHERE alias_key=?', [newName.toLowerCase()]);
      await conn.query('INSERT INTO o2d_dealer_aliases (alias_key, counter_name, created_by) VALUES (?,?,?) ON DUPLICATE KEY UPDATE counter_name=VALUES(counter_name)',
        [oldName.toLowerCase().slice(0, 191), newName, req.session.userId]);
    });
    res.json({ success: true, name: newName });
  } catch (err) { sendServerError(res, err); }
});

app.get('/api/o2d-fms/dealers', requireAuth, async (req, res) => {
  try {
    if (!(await canAccessDealers(req))) return res.status(403).json({ error: 'You do not have access to Dealers' });
    const [debtorsMap, dealerRows, paymentRows, orders, billsAgingByParty, tallyPaymentsByParty, tallyRatingByParty, ledgerBalancesByParty, vouchers] = await Promise.all([
      getDebtorsMap().catch(() => ({})), // dealer directory shouldn't 500 just because the debtors sheet hiccups — Outstanding just shows blank
      withDealerTables(() => db.query("SELECT d.*, DATE_FORMAT(d.hidden_at,'%Y-%m-%d %H:%i:%s') AS hidden_at_s, u.name AS details_by_name FROM o2d_dealers d LEFT JOIN users u ON u.id=d.details_updated_by")).then(([r]) => r),
      withDealerTables(() => db.query('SELECT * FROM o2d_dealer_payments ORDER BY due_date')).then(([r]) => r),
      getO2dOrders().catch(() => []), // dealer directory shouldn't 500 just because the orders sheet hiccups
      getBillsReceivableAgingByDealer().catch(() => ({})), // same — Tally sync sheet hiccup shouldn't break the whole page
      getTallyPaymentsByDealer().catch(() => ({})),
      getTallyPaymentPerformanceByDealer().catch(() => ({})),
      getLedgerBalancesByDealer().catch(() => ({})),
      getLedgerVouchers().catch(() => ({ byKey: {}, legIndex: {} }))
    ]);

    const byKey = {}; // lowercased counter name -> merged dealer record
    const aliasOf = await getDealerAliasMap();
    const dfl = (v, def) => v !== null && v !== undefined ? Number(v) : def;
    const ensure = (name) => {
      let key = name.trim().toLowerCase();
      if (!key) return null;
      if (aliasOf[key]) { name = aliasOf[key]; key = name.trim().toLowerCase(); }
      if (!byKey[key]) byKey[key] = { name: name.trim(), city: '', phone: '', creditLimit: DEALER_DEFAULT_CREDIT_LIMIT, creditDays: DEALER_DEFAULT_CREDIT_DAYS, outstanding: null,
        locationLat: null, locationLng: null, locationAddress: '', kyc: { aadhar: null, pan: null, gst: null, shop: null },
        lastOrder: null, payments: [] };
      return byKey[key];
    };

    Object.values(debtorsMap).forEach(v => { const d = ensure(v.name); if (d) d.outstanding = v.outstanding; });

    dealerRows.forEach(row => {
      const d = ensure(row.counter_name);
      if (!d) return;
      d.name = row.counter_name; // profile row is the authoritative display name/casing
      d.city = row.city || '';
      d.phone = row.phone || '';
      d.creditLimit = dfl(row.credit_limit, DEALER_DEFAULT_CREDIT_LIMIT);
      d.creditDays = dfl(row.credit_days, DEALER_DEFAULT_CREDIT_DAYS);
      d.tallyName = row.tally_name || '';
      d.locationLat = row.location_lat !== null ? Number(row.location_lat) : null;
      d.locationLng = row.location_lng !== null ? Number(row.location_lng) : null;
      d.locationAddress = row.location_address || '';
      d.kyc = { aadhar: row.kyc_aadhar_url || null, pan: row.kyc_pan_url || null, gst: row.kyc_gst_url || null, shop: row.kyc_shop_url || null };
      d.details = { ownerName: row.owner_name || '', altPhone: row.alt_phone || '', area: row.area || '', address: row.address || '',
        dob: row.dob || '', anniversary: row.anniversary || '', gstNo: row.gst_no || '', notes: row.notes || '',
        updatedAt: row.details_updated_at || '', updatedBy: row.details_by_name || '' };
      d.hiddenAt = row.hidden_at_s || '';
      d.bilty = row.bilty_url || row.bilty_transport ? { url: row.bilty_url || '', transport: row.bilty_transport || '', updatedAt: row.bilty_updated_at || '' } : null;
    });

    paymentRows.forEach(p => { const d = ensure(p.counter_name); if (d) d.payments.push(p); });

    // Dealers that came in through the New Dealer Onboarding form (Lead FMS) —
    // the form's details open from here; there is no separate list for them.
    try {
      const [onb] = await withLeadTables(() => db.query('SELECT id, code, shop_name FROM dealer_onboardings ORDER BY id'));
      onb.forEach(o => { const d = ensure(o.shop_name); if (d) d.onboarding = { id: o.id, code: o.code }; });
    } catch (e) { console.warn('dealer onboardings not merged:', e.message); }

    // getO2dOrders() already groups by Order No. — just take each dealer's most recent
    orders.forEach(o => {
      if (!o.counterName) return;
      const d = ensure(o.counterName);
      if (!d) return;
      if (!d.lastOrder || o.timestamp > d.lastOrder.timestamp) {
        d.lastOrder = { timestamp: o.timestamp, orderNo: o.orderNo, qty: o.qty, amount: o.amount, area: o.area };
      }
    });

    // Only attaches aging to dealers we already know about (via debtors/
    // dealer profile/orders) — doesn't create new dealer rows just because
    // Tally has a party by that name; most Tally parties aren't O2D dealers.
    // Outstanding provisionally takes this (bill-wise, synced daily) over
    // the older Group Summary debtors sheet — but only provisionally: a
    // dealer whose invoices aren't tracked bill-by-bill in Tally has real
    // dues that never appear here at all, so the real Ledger Closing
    // Balance below (when available) overrides this with the true total.
    // The bucket breakdown itself stays as-is either way — it can only ever
    // reflect whatever portion was bill-tracked.
    // Tally party name -> dealers: the dealer's own name, or the Tally name
    // linked to it ("🔗 Tally naam jodo" on the Statement) when Tally spells it
    // differently. A linked name also matches a duplicate row with that name.
    const byTally = {};
    Object.values(byKey).forEach(d => { d.tallyKey = (d.tallyName || d.name).trim().toLowerCase(); (byTally[d.tallyKey] = byTally[d.tallyKey] || []).push(d); });
    const tallyDealers = key => byTally[key] || [];
    Object.values(billsAgingByParty).forEach(agg => {
      const key = agg.name.trim().toLowerCase();
      for (const d of tallyDealers(key)) { d.aging = { buckets: agg.buckets, total: agg.total, billCount: agg.count }; d.outstanding = agg.total; }
    });

    // Real ledger balance — the source of truth for Outstanding whenever
    // Tally has it, since it reflects the party's actual running account
    // regardless of bill-wise tracking. Wins over both the bill-wise total
    // above and the legacy debtors-sheet fallback.
    Object.values(ledgerBalancesByParty).forEach(lb => {
      const key = lb.name.trim().toLowerCase();
      for (const d of tallyDealers(key)) d.outstanding = lb.closingBalance;
    });

    // Tally's own "Bills Receivable" bill-wise matching turned out
    // unreliable both ways — some dealers carry years-old invoices that
    // were actually settled but never left the report (some 8+ years
    // overdue on a real sync), while others have genuinely-unpaid older
    // invoices that quietly drop OUT of the report even though the real
    // Ledger Closing Balance is well above the bill-wise total (confirmed
    // case: bill-wise showed one ₹17,500 invoice, real balance was
    // ₹29,221 — ₹11,721 of real debt Bills Receivable just didn't list).
    // Wherever this FY's actual vouchers are available for a dealer, our
    // own FIFO aging (computeFifoAging) replaces the bill-wise buckets
    // entirely instead of trying to patch or merely distrust them.
    Object.values(byKey).forEach(d => {
      const key = d.tallyKey;
      const ledger = ledgerBalancesByParty[key];
      const fifo = vouchers.legIndex[key] ? computeFifoAging(key, vouchers, ledger || null) : null;
      if (fifo && fifo.billCount) {
        d.aging = fifo;
      } else if (fifo) {
        d.aging = null; // vouchers exist this FY but nothing's actually open — trust that over stale bill-wise data
      }
      // else: no FY voucher data for this dealer at all — leave whatever bill-wise aging was set above as a fallback
    });

    // Outstanding = only bills past the dealer's credit days (client
    // 2026-10-24: "billed date ke 30 din baad hi outstanding mai aayega").
    // The full balance stays as outstandingAll. Needs bill-level (FIFO) data;
    // without it the full balance is shown as before.
    Object.values(byKey).forEach(d => {
      const open = d.aging && d.aging.openBills;
      if (d.outstanding == null || !open || d.outstanding <= 0) return;
      d.outstandingAll = d.outstanding;
      d.outstanding = Math.min(d.outstandingAll, Math.round(open.filter(b => b.daysOverdue > d.creditDays).reduce((s, b) => s + b.remaining, 0)));
    });

    // Same matching rule — only for dealers we already know, most recent 5.
    Object.entries(tallyPaymentsByParty).forEach(([key, list]) => {
      for (const d of tallyDealers(key)) d.tallyPayments = list.slice(-5).reverse();
    });

    const dealers = Object.values(byKey).map(d => {
      // Real Tally-derived on-time/late (bill-by-bill payments joined
      // against BillRegistry due dates) wins when there's enough of it to
      // mean something; otherwise falls back to manually logged payments.
      const tallyRating = tallyRatingByParty[d.tallyKey];
      const manualRating = computeDealerRating(d.payments);
      const rating = (tallyRating && tallyRating.total > 0) ? { ...tallyRating, source: 'tally' } : { ...manualRating, source: 'manual' };
      const creditTier = computeCreditTier(d.aging ? d.aging.buckets : {}, d.aging ? d.aging.total : 0, rating.source === 'tally' ? rating : null);
      const kycCount = Object.values(d.kyc).filter(Boolean).length;
      delete d.payments; delete d.tallyKey;
      return { ...d, kycCount, rating, creditTier };
    }).filter(d => !d.hiddenAt || (d.lastOrder && String(d.lastOrder.timestamp) > d.hiddenAt)).sort((a, b) => a.name.localeCompare(b.name));

    res.json({ dealers });
  } catch (err) { sendServerError(res, err); }
});

// Command palette (UI Phase B): a few dealers by name / city / phone, straight
// from MySQL — no sheet reads, so typing in Ctrl+K stays cheap.
app.get('/api/quick-search', requireAuth, async (req, res) => {
  try {
    const q = String(req.query.q || '').trim().slice(0, 60);
    if (q.length < 2 || !(await canAccessDealers(req))) return res.json({ dealers: [] });
    const safe = q.replace(/[\\%_]/g, '\\$&'); // LIKE wildcards typed by the user match literally
    const like = `%${safe}%`;
    const [rows] = await withDealerTables(() => db.query(
      'SELECT counter_name, city, phone FROM o2d_dealers WHERE counter_name LIKE ? OR city LIKE ? OR phone LIKE ? ORDER BY (counter_name LIKE ?) DESC, counter_name LIMIT 8',
      [like, like, like, `${safe}%`]));
    res.json({ dealers: rows.map(r => ({ name: r.counter_name, city: r.city || '', phone: r.phone || '' })) });
  } catch (err) { sendServerError(res, err); }
});

// One mobile = one dealer (client list 2026-10-26 #18: "duplicate dealer na bane, mobile number
// unique hai, vahan se check kar lo"). Returns the other dealer already holding this number
// (last 10 digits, phone or alt phone), or null. `except` = the dealer being saved.
async function dealerWithPhone(phone, except) {
  const n = sfmsNormalizeMobile(String(phone || '').trim());
  if (!n) return null;
  const last10 = n.slice(-10);
  const [rows] = await withDealerTables(() => db.query(
    `SELECT counter_name FROM o2d_dealers WHERE (RIGHT(REGEXP_REPLACE(COALESCE(phone,''),'[^0-9]',''),10)=? OR RIGHT(REGEXP_REPLACE(COALESCE(alt_phone,''),'[^0-9]',''),10)=?)
       AND hidden_at IS NULL AND LOWER(TRIM(counter_name))<>? LIMIT 1`, [last10, last10, String(except || '').trim().toLowerCase()]));
  return rows[0] ? rows[0].counter_name : null;
}
const dupPhoneMsg = (phone, other) => `Ye mobile (${phone}) pehle se dealer "${other}" ka hai — naya dealer mat banao, wahi dealer use karo (galat ho to pehle uska number sudharo)`;
app.post('/api/o2d-fms/dealers', requireAuth, async (req, res) => {
  try {
    if (!(await canAccessDealers(req))) return res.status(403).json({ error: 'You do not have access to Dealers' });
    const { name, city, phone } = req.body;
    if (!name || !name.trim()) return res.status(400).json({ error: 'Dealer name is required' });
    const other = phone ? await dealerWithPhone(phone, name) : null;
    if (other) return res.status(409).json({ error: dupPhoneMsg(phone, other) });
    await withDealerTables(() => db.query(
      'INSERT INTO o2d_dealers (counter_name, city, phone) VALUES (?,?,?) ON DUPLICATE KEY UPDATE city=VALUES(city), phone=VALUES(phone)',
      [name.trim(), city || null, phone || null]
    ));
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

app.put('/api/o2d-fms/dealers/:name', requireAuth, async (req, res) => {
  try {
    if (!canEditDealers(req)) return res.status(403).json({ error: 'Only admins can set a dealer\'s credit limit' });
    const name = req.params.name.trim();
    const { city, phone, creditLimit, creditDays } = req.body;
    if (creditLimit !== '' && creditLimit !== undefined && creditLimit !== null && !(Number(creditLimit) >= 0)) {
      return res.status(400).json({ error: 'Credit limit must be a non-negative number' });
    }
    if (creditDays !== undefined) {
      const cd = creditDays === '' || creditDays === null ? null : Number(creditDays);
      if (cd !== null && !(Number.isInteger(cd) && cd >= 0 && cd <= 365)) return res.status(400).json({ error: 'Credit days 0 se 365 ke beech likhein' });
      await withDealerTables(async () => { await ensureDealerDetailCols(); await db.query('INSERT INTO o2d_dealers (counter_name, credit_days) VALUES (?,?) ON DUPLICATE KEY UPDATE credit_days=VALUES(credit_days)', [name, cd]); });
      if (creditLimit === undefined && city === undefined && phone === undefined) return res.json({ success: true });
    }
    await withDealerTables(() => db.query(
      `INSERT INTO o2d_dealers (counter_name, city, phone, credit_limit) VALUES (?,?,?,?)
       ON DUPLICATE KEY UPDATE
         city = COALESCE(VALUES(city), city),
         phone = COALESCE(VALUES(phone), phone),
         credit_limit = IF(?, VALUES(credit_limit), credit_limit)`,
      // creditLimit omitted entirely (e.g. the Statement's phone-only save)
      // keeps the existing limit; an explicit '' / null still clears it.
      [name, city || null, phone || null, (creditLimit === '' || creditLimit === undefined || creditLimit === null) ? null : Number(creditLimit), creditLimit !== undefined ? 1 : 0]
    ));
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

app.put('/api/o2d-fms/dealers/:name/details', requireAuth, async (req, res) => {
  try {
    // Client, 2026-10-16: only Admin edits a dealer's details.
    if (!canEditDealers(req)) return res.status(403).json({ error: 'Dealer details sirf Admin badal sakta hai' });
    const name = req.params.name.trim();
    const b = req.body || {};
    const str = (v, n) => String(v == null ? '' : v).trim().slice(0, n) || null;
    const ymd = v => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? v : null;
    for (const k of ['dob', 'anniversary']) if (b[k] && !ymd(b[k])) return res.status(400).json({ error: 'Date galat hai' });
    const phone = str(b.phone, 50), alt = str(b.altPhone, 50);
    for (const p of [phone, alt]) if (p && !sfmsNormalizeMobile(p)) return res.status(400).json({ error: `Mobile number galat lag raha hai: ${p}` });
    // Only a number that changed is checked — old duplicates (same phone under spelling variants) can still save their details.
    const [[cur]] = await withDealerTables(() => db.query('SELECT phone, alt_phone FROM o2d_dealers WHERE counter_name=?', [name]));
    const ten = v => String(v || '').replace(/\D/g, '').slice(-10);
    const had = new Set([cur && cur.phone, cur && cur.alt_phone].map(ten).filter(Boolean));
    for (const p of [phone, alt]) { const other = p && !had.has(ten(p)) ? await dealerWithPhone(p, name) : null; if (other) return res.status(409).json({ error: dupPhoneMsg(p, other) }); }
    const lat = Number(b.locationLat), lng = Number(b.locationLng);
    const hasLoc = b.locationLat != null && b.locationLat !== '' && isFinite(lat) && isFinite(lng) && (lat || lng);
    const vals = [str(b.ownerName, 255), phone, alt, str(b.city, 255), str(b.area, 255), str(b.address, 1000), ymd(b.dob), ymd(b.anniversary),
      str(b.gstNo, 30) && str(b.gstNo, 30).toUpperCase(), str(b.notes, 1000)];
    await withDealerTables(() => db.query(
      `INSERT INTO o2d_dealers (counter_name, owner_name, phone, alt_phone, city, area, address, dob, anniversary, gst_no, notes, details_updated_by, details_updated_at${hasLoc ? ', location_lat, location_lng' : ''})
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,NOW()${hasLoc ? ',?,?' : ''})
       ON DUPLICATE KEY UPDATE owner_name=VALUES(owner_name), phone=VALUES(phone), alt_phone=VALUES(alt_phone), city=VALUES(city), area=VALUES(area),
         address=VALUES(address), dob=VALUES(dob), anniversary=VALUES(anniversary), gst_no=VALUES(gst_no), notes=VALUES(notes),
         details_updated_by=VALUES(details_updated_by), details_updated_at=NOW()${hasLoc ? ', location_lat=VALUES(location_lat), location_lng=VALUES(location_lng)' : ''}`,
      [name, ...vals, req.session.userId, ...(hasLoc ? [lat, lng] : [])]));
    if (phone) await syncDealerPhone(name, phone, 'dealer');
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

