// ── Upload from the ERP (client, 2026-10-18: no third-party sync app) ──
// The salesman picks his recordings on the phone; each file goes straight
// from the browser to Google Drive through a resumable session this server
// opens with the service account (Origin passed, so Google allows the
// browser's PUT) — the audio never passes through Vercel. Files land in
// "<root folder>/<salesman name>/", which the Apps Script reads (folder mode).
const CALL_FOLDER_KEY = 'call_rec_folder_id', CALL_USER_FOLDERS_KEY = 'call_rec_user_folders';
let _callDriveAuth = null;
async function callDriveToken() {
  if (!_callDriveAuth) {
    const { google } = require('googleapis');
    _callDriveAuth = new google.auth.GoogleAuth({ credentials: loadGoogleCreds(), scopes: ['https://www.googleapis.com/auth/drive'] });
  }
  const t = await (await _callDriveAuth.getClient()).getAccessToken();
  return t && t.token ? t.token : t;
}
async function callCanUpload(req) {
  if (await callSeesAll(req)) return true;
  const [[sp]] = await withPlTables(() => db.query("SELECT user_id FROM salesman_profiles WHERE user_id=? AND o2d_names IS NOT NULL AND o2d_names<>''", [req.session.userId]));
  return !!sp;
}
// The user's own sub-folder (made on first upload, or an existing one with
// his name), remembered per root so a changed root gets new sub-folders.
async function callUserFolder(userId, userName) {
  const root = await getAppSetting(CALL_FOLDER_KEY);
  if (!root) { const e = new Error('Recordings ka folder abhi set nahi hai — Admin: Call Reports → ⚙️ Setup'); e.status = 400; throw e; }
  let map = {};
  try { map = JSON.parse((await getAppSetting(CALL_USER_FOLDERS_KEY)) || '{}') || {}; } catch (e) { map = {}; }
  if (map[userId] && map[userId].root === root) return map[userId];
  const drive = await getDriveClient();
  const name = String(userName || `User ${userId}`).replace(/['\\]/g, '').trim().slice(0, 100);
  const found = await drive.files.list({ corpora: 'allDrives', includeItemsFromAllDrives: true, supportsAllDrives: true, fields: 'files(id)',
    q: `'${root}' in parents and trashed=false and mimeType='application/vnd.google-apps.folder' and name='${name}'` });
  let id = found.data.files[0] && found.data.files[0].id;
  if (!id) id = (await drive.files.create({ supportsAllDrives: true, fields: 'id', requestBody: { name, mimeType: 'application/vnd.google-apps.folder', parents: [root] } })).data.id;
  map[userId] = { root, id, name };
  await setAppSetting(CALL_USER_FOLDERS_KEY, JSON.stringify(map));
  // The script names each call's source after this folder — tie it to the user.
  const dmap = await callDriveMap();
  if (Number(dmap[name]) !== Number(userId)) { dmap[name] = Number(userId); await setAppSetting(CALL_DRIVE_MAP_KEY, JSON.stringify(dmap)); }
  return map[userId];
}
const callUploadName = n => callStr(String(n || '').replace(/[\\/]/g, '_'), 255);
// Which of the picked files are new (re-picking the whole folder every day is fine).
app.post('/api/call-uploads/check', requireAuth, async (req, res) => {
  try {
    if (!(await callCanUpload(req))) return res.status(403).json({ error: 'Upload sirf salesmen ke liye' });
    const names = [...new Set((Array.isArray(req.body && req.body.names) ? req.body.names : []).slice(0, 2000).map(callUploadName).filter(Boolean))];
    if (!names.length) return res.json({ fresh: [] });
    const uid = Number(req.session.userId);
    const [[up], [rec]] = await withCallTable(() => Promise.all([
      db.query('SELECT file_name FROM call_uploads WHERE user_id=? AND file_name IN (?)', [uid, names]),
      db.query('SELECT file_name FROM call_recordings WHERE salesman_user_id=? AND file_name IN (?)', [uid, names])
    ]));
    const have = new Set([...up, ...rec].map(r => r.file_name));
    res.json({ fresh: names.filter(n => !have.has(n)) });
  } catch (err) { sendServerError(res, err); }
});
// Open Drive upload sessions for up to 10 files; the browser PUTs each file to its url.
app.post('/api/call-uploads/start', requireAuth, async (req, res) => {
  try {
    if (!(await callCanUpload(req))) return res.status(403).json({ error: 'Upload sirf salesmen ke liye' });
    const files = (Array.isArray(req.body && req.body.files) ? req.body.files : []).slice(0, 10);
    const folder = await callUserFolder(req.session.userId, req.session.name);
    const token = await callDriveToken();
    const origin = req.headers.origin || `${req.headers['x-forwarded-proto'] || req.protocol}://${req.get('host')}`;
    const sessions = await Promise.all(files.map(async f => {
      const name = callUploadName(f && f.name), size = Number(f && f.size) || 0;
      if (!name || !(size > 0) || size > 50 * 1024 * 1024) return { name, error: 'File khali ya 50 MB se badi' };
      // Public `properties` (appProperties would be private to this service
      // account — the Apps Script, another app, couldn't read them).
      const properties = { erpUser: String(req.session.userId) };
      if (CALL_DT_RX.test((f && f.recordedAt) || '')) properties.recordedAt = f.recordedAt;
      const r = await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&supportsAllDrives=true&fields=id', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json; charset=UTF-8', Origin: origin,
          'X-Upload-Content-Type': callStr(f.type, 100) || 'application/octet-stream', 'X-Upload-Content-Length': String(size) },
        body: JSON.stringify({ name, parents: [folder.id], properties })
      });
      const url = r.headers.get('location');
      return r.ok && url ? { name, url } : { name, error: `Drive ${r.status}: ${(await r.text()).slice(0, 200)}` };
    }));
    res.json({ sessions });
  } catch (err) {
    if (err.status === 400) return res.status(400).json({ error: err.message });
    if (err.code === 404 || err.code === 403) return res.status(400).json({ error: 'Recordings folder tak access nahi — service account ko us Shared Drive me Content manager banao' });
    sendServerError(res, err);
  }
});
app.post('/api/call-uploads/done', requireAuth, async (req, res) => {
  try {
    const files = (Array.isArray(req.body && req.body.files) ? req.body.files : []).slice(0, 200)
      .map(f => [Number(req.session.userId), callUploadName(f && f.name), Number(f && f.size) || null, callStr(f && f.fileId, 100) || null]).filter(r => r[1]);
    if (files.length) await withCallTable(() => db.query('INSERT IGNORE INTO call_uploads (user_id, file_name, size_bytes, drive_file_id) VALUES ?', [files]));
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});
// Admin: the "Call Recordings" folder (link or id) the uploads go into.
app.put('/api/call-reports-admin/folder', requireAuth, requireAdmin, async (req, res) => {
  try {
    const raw = callStr(req.body && req.body.folder, 300);
    const id = (/\/folders\/([\w-]{10,})/.exec(raw) || /^([\w-]{10,})$/.exec(raw) || [])[1];
    if (!id) return res.status(400).json({ error: 'Folder ka link ya ID daalo' });
    const drive = await getDriveClient();
    let meta;
    try { meta = (await drive.files.get({ fileId: id, supportsAllDrives: true, fields: 'id, name, mimeType, driveId, capabilities(canAddChildren)' })).data; }
    catch (e) { return res.status(400).json({ error: 'Ye folder service account ko nahi dikh raha — Shared Drive me akhileshvyas@reactwebappav.iam.gserviceaccount.com ko Content manager banao' }); }
    if (meta.mimeType !== 'application/vnd.google-apps.folder') return res.status(400).json({ error: 'Ye folder nahi hai' });
    if (!meta.driveId) return res.status(400).json({ error: 'Folder kisi Shared Drive ke andar hona chahiye (My Drive me service account file nahi bana sakta)' });
    if (!meta.capabilities || !meta.capabilities.canAddChildren) return res.status(400).json({ error: 'Service account is folder me file nahi daal sakta — Content manager banao' });
    await setAppSetting(CALL_FOLDER_KEY, id);
    res.json({ success: true, folder: { id, name: meta.name } });
  } catch (err) { sendServerError(res, err); }
});

// ══════════════════════════════════════════════════════
// SALES SCHEDULE (client, 2026-10-12: "sales person ka scheduler — har mahine
// ka schedule kab kis dealer ke paas jana hai"). A manager (admin / HOD / PC
// / Vishal & Ajay) plans each salesman's month dealer by dealer; the salesman
// sees his own visits and records a visit with any of: check-in photo + GPS,
// order value / remark, next visit date (which adds the next visit).
// ══════════════════════════════════════════════════════
async function ensureSalesScheduleTable() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS sales_schedule (
      id INT AUTO_INCREMENT PRIMARY KEY,
      user_id INT NOT NULL,
      visit_date DATE NOT NULL,
      dealer_name VARCHAR(255) NOT NULL,
      purpose VARCHAR(255),
      status VARCHAR(20) NOT NULL DEFAULT 'planned',
      visited_at DATETIME,
      photo VARCHAR(500),
      lat DECIMAL(10,7), lng DECIMAL(10,7),
      distance_m INT,
      order_value DECIMAL(12,2),
      remark VARCHAR(500),
      next_visit_date DATE,
      created_by_name VARCHAR(255),
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      INDEX (user_id, visit_date)
    )`);
  // v1 of the client's paper scheduler (2026-10-13): each day of a salesman's
  // month is Full / Half / No visit (normal beat) or an upcountry place, and
  // every counter has its salesman + beat weekday (1 = Mon … 7 = Sun).
  await db.query(`
    CREATE TABLE IF NOT EXISTS sales_day_plan (
      id INT AUTO_INCREMENT PRIMARY KEY,
      user_id INT NOT NULL,
      plan_date DATE NOT NULL,
      plan VARCHAR(10) NOT NULL,
      place VARCHAR(120),
      updated_by VARCHAR(255),
      UNIQUE KEY uq_user_day (user_id, plan_date)
    )`);
  await db.query(`
    CREATE TABLE IF NOT EXISTS sales_counters (
      id INT AUTO_INCREMENT PRIMARY KEY,
      counter_name VARCHAR(255) NOT NULL UNIQUE,
      city VARCHAR(255),
      user_id INT,
      beat_day TINYINT,
      updated_by VARCHAR(255),
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    )`);
}
async function withSalesSchedule(fn) {
  try { return await fn(); }
  catch (e) { if (e.code !== 'ER_NO_SUCH_TABLE') throw e; await ensureSalesScheduleTable(); return await fn(); }
}
async function ssIsManager(req) {
  return ['admin', 'hod', 'pc'].includes(req.session.role) || await plIsViewer(req);
}
const SS_SELECT = `SELECT s.id, s.user_id, u.name AS user_name, DATE_FORMAT(s.visit_date,'%Y-%m-%d') AS visit_date, s.dealer_name, s.purpose, s.status,
  DATE_FORMAT(s.visited_at,'%Y-%m-%d %H:%i') AS visited_at, s.photo, s.lat, s.lng, s.distance_m, s.order_value, s.remark,
  DATE_FORMAT(s.next_visit_date,'%Y-%m-%d') AS next_visit_date, s.created_by_name
  FROM sales_schedule s LEFT JOIN users u ON u.id=s.user_id`;

app.get('/api/sales-schedule', requireAuth, async (req, res) => {
  try {
    const month = /^\d{4}-\d{2}$/.test(req.query.month || '') ? req.query.month : new Date().toISOString().slice(0, 7);
    const manager = await ssIsManager(req);
    const userId = manager ? (req.query.userId === 'all' ? null : Number(req.query.userId) || null) : Number(req.session.userId);
    const start = `${month}-01`, end = ymdAddDays(`${month}-01`, 40).slice(0, 7) + '-01';
    const [visits] = await withSalesSchedule(() => db.query(
      `${SS_SELECT} WHERE s.visit_date >= ? AND s.visit_date < ?${userId ? ' AND s.user_id=?' : ''} ORDER BY s.visit_date, s.dealer_name`,
      userId ? [start, end, userId] : [start, end]));
    let salesmen = [], dealers = [];
    if (manager) {
      // Salesmen first (O2D-linked profile or KM-tracked), then everyone else.
      const [u] = await db.query(`SELECT u.id, u.name, (sp.user_id IS NOT NULL OR u.track_km=1) AS is_sales
        FROM users u LEFT JOIN salesman_profiles sp ON sp.user_id=u.id
        WHERE u.is_active=1 AND (u.role IS NULL OR u.role<>'vendor') ORDER BY is_sales DESC, u.name`).catch(async e => {
          if (e.code !== 'ER_NO_SUCH_TABLE') throw e;
          return db.query("SELECT id, name, track_km=1 AS is_sales FROM users WHERE is_active=1 AND (role IS NULL OR role<>'vendor') ORDER BY is_sales DESC, name");
        });
      salesmen = u.map(x => ({ id: x.id, name: x.name, isSales: !!Number(x.is_sales) }));
      const [d] = await withDealerTables(() => db.query('SELECT counter_name AS name, city FROM o2d_dealers ORDER BY counter_name'));
      dealers = d;
    }
    const [[plans], [beat], [dm]] = await withSalesSchedule(() => Promise.all([
      db.query(`SELECT user_id, DATE_FORMAT(plan_date,'%Y-%m-%d') AS d, plan, place FROM sales_day_plan
                WHERE plan_date >= ? AND plan_date < ?${userId ? ' AND user_id=?' : ''}`, userId ? [start, end, userId] : [start, end]),
      db.query('SELECT counter_name, city, user_id, beat_day FROM sales_counters'),
      withDealerTables(() => db.query('SELECT counter_name, city FROM o2d_dealers'))
    ]));
    // Counters = Dealer Master + any counter only in the beat list, with its salesman / day.
    const byKey = {};
    dm.forEach(x => { byKey[x.counter_name.toLowerCase()] = { name: x.counter_name, city: x.city || '', userId: null, day: null }; });
    beat.forEach(x => {
      const c = byKey[x.counter_name.toLowerCase()] = byKey[x.counter_name.toLowerCase()] || { name: x.counter_name, city: '', userId: null, day: null };
      if (x.city) c.city = x.city;
      c.userId = x.user_id; c.day = x.beat_day;
    });
    const counters = Object.values(byKey).sort((a, b) => a.name.localeCompare(b.name));
    res.json({ month, isManager: manager, userId, visits, salesmen, dealers, dayPlans: plans.map(p => ({ userId: p.user_id, date: p.d, plan: p.plan, place: p.place || '' })), counters });
  } catch (err) { sendServerError(res, err); }
});

// Manager: add one or more dealers to a salesman's day(s).
app.post('/api/sales-schedule', requireAuth, async (req, res) => {
  try {
    if (!(await ssIsManager(req))) return res.status(403).json({ error: 'Only a manager can plan the schedule' });
    const userId = Number(req.body.userId);
    const dates = (Array.isArray(req.body.dates) ? req.body.dates : [req.body.date]).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d || ''));
    const dealers = (Array.isArray(req.body.dealers) ? req.body.dealers : []).map(d => String(d || '').trim().slice(0, 255)).filter(Boolean);
    const purpose = String(req.body.purpose || '').trim().slice(0, 255);
    if (!userId || !dates.length || !dealers.length) return res.status(400).json({ error: 'Salesman, date and dealer are required' });
    if (dates.length * dealers.length > 400) return res.status(400).json({ error: 'Too many visits at once' });
    const [[u]] = await db.query('SELECT id FROM users WHERE id=?', [userId]);
    if (!u) return res.status(400).json({ error: 'Salesman not found' });
    // Skip a dealer already planned for that salesman on that day.
    const [existing] = await withSalesSchedule(() => db.query(
      "SELECT DATE_FORMAT(visit_date,'%Y-%m-%d') AS d, LOWER(dealer_name) AS n FROM sales_schedule WHERE user_id=? AND visit_date IN (?)", [userId, dates]));
    const have = new Set(existing.map(r => `${r.d}|${r.n}`));
    const rows = [];
    dates.forEach(d => dealers.forEach(n => { if (!have.has(`${d}|${n.toLowerCase()}`)) { have.add(`${d}|${n.toLowerCase()}`); rows.push([userId, d, n, purpose, req.session.name || '']); } }));
    if (rows.length) await db.query('INSERT INTO sales_schedule (user_id, visit_date, dealer_name, purpose, created_by_name) VALUES ?', [rows]);
    res.json({ success: true, added: rows.length, skipped: dates.length * dealers.length - rows.length });
  } catch (err) { sendServerError(res, err); }
});

// Manager: CSV upload (client, 2026-10-12) — rows of { salesman (name or
// id), date (YYYY-MM-DD, parsed in the browser), dealer, purpose }. Rows
// already planned are skipped; bad rows come back with their line number.
app.post('/api/sales-schedule/bulk', requireAuth, async (req, res) => {
  try {
    if (!(await ssIsManager(req))) return res.status(403).json({ error: 'Only a manager can plan the schedule' });
    const rows = Array.isArray(req.body.rows) ? req.body.rows : [];
    if (!rows.length) return res.status(400).json({ error: 'CSV mein koi row nahi mili' });
    if (rows.length > 3000) return res.status(400).json({ error: 'Ek baar mein max 3000 rows' });
    const [users] = await db.query("SELECT id, name FROM users WHERE is_active=1 AND (role IS NULL OR role<>'vendor')");
    const byName = new Map(users.map(u => [u.name.trim().toLowerCase(), u.id]));
    const ids = new Set(users.map(u => u.id));
    const errors = [], good = [];
    rows.forEach(r => {
      const who = String(r.salesman || '').trim();
      const uid = ids.has(Number(who)) ? Number(who) : byName.get(who.toLowerCase());
      const dealer = String(r.dealer || '').trim().slice(0, 255);
      if (!uid) return errors.push({ line: r.line, error: `Salesman "${who}" nahi mila` });
      if (!/^\d{4}-\d{2}-\d{2}$/.test(r.date || '')) return errors.push({ line: r.line, error: 'Date galat hai' });
      if (!dealer) return errors.push({ line: r.line, error: 'Dealer khaali hai' });
      good.push({ uid, date: r.date, dealer, purpose: String(r.purpose || '').trim().slice(0, 255) });
    });
    let added = 0, skipped = 0;
    if (good.length) {
      const uids = [...new Set(good.map(g => g.uid))], dates = [...new Set(good.map(g => g.date))];
      const [existing] = await withSalesSchedule(() => db.query(
        "SELECT user_id, DATE_FORMAT(visit_date,'%Y-%m-%d') AS d, LOWER(dealer_name) AS n FROM sales_schedule WHERE user_id IN (?) AND visit_date IN (?)", [uids, dates]));
      const have = new Set(existing.map(e => `${e.user_id}|${e.d}|${e.n}`));
      const ins = [];
      good.forEach(g => {
        const k = `${g.uid}|${g.date}|${g.dealer.toLowerCase()}`;
        if (have.has(k)) { skipped++; return; }
        have.add(k);
        ins.push([g.uid, g.date, g.dealer, g.purpose, req.session.name || '']);
      });
      if (ins.length) await db.query('INSERT INTO sales_schedule (user_id, visit_date, dealer_name, purpose, created_by_name) VALUES ?', [ins]);
      added = ins.length;
    }
    res.json({ success: true, added, skipped, errors });
  } catch (err) { sendServerError(res, err); }
});

// "Full visit" / "Half" / "No visit" / anything else = an upcountry place.
const SS_PLAN_KINDS = ['full', 'half', 'none', 'up'];
function ssParsePlan(text) {
  const t = String(text || '').trim();
  const k = t.toLowerCase().replace(/\s+/g, ' ');
  if (!k) return null;
  if (/^full( visit)?$/.test(k)) return { plan: 'full', place: '' };
  if (/^half( visit)?$/.test(k)) return { plan: 'half', place: '' };
  if (/^no( visit)?$|^(off|leave|chutti)$/.test(k)) return { plan: 'none', place: '' };
  return { plan: 'up', place: t.slice(0, 120) };
}
const SS_DAYS = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7, som: 1, man: 2, bud: 3, gur: 4, guru: 4, shu: 5, sha: 6, rav: 7 };
function ssParseDay(v) {
  const n = Number(v);
  if (Number.isInteger(n) && n >= 1 && n <= 7) return n;
  const k = String(v || '').trim().toLowerCase();
  return SS_DAYS[k.slice(0, 4)] || SS_DAYS[k.slice(0, 3)] || null;
}

// Manager: set (or clear) one day's plan for a salesman.
app.put('/api/sales-schedule/day-plan', requireAuth, async (req, res) => {
  try {
    if (!(await ssIsManager(req))) return res.status(403).json({ error: 'Only a manager can plan the schedule' });
    const userId = Number(req.body.userId), date = String(req.body.date || '');
    if (!userId || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ error: 'Salesman and date are required' });
    const plan = String(req.body.plan || '');
    if (!plan) {
      await withSalesSchedule(() => db.query('DELETE FROM sales_day_plan WHERE user_id=? AND plan_date=?', [userId, date]));
      return res.json({ success: true, cleared: true });
    }
    if (!SS_PLAN_KINDS.includes(plan)) return res.status(400).json({ error: 'Invalid plan' });
    const place = plan === 'up' ? String(req.body.place || '').trim().slice(0, 120) : '';
    if (plan === 'up' && !place) return res.status(400).json({ error: 'Upcountry ka shehar likhein' });
    await withSalesSchedule(() => db.query(
      `INSERT INTO sales_day_plan (user_id, plan_date, plan, place, updated_by) VALUES (?,?,?,?,?)
       ON DUPLICATE KEY UPDATE plan=VALUES(plan), place=VALUES(place), updated_by=VALUES(updated_by)`,
      [userId, date, plan, place || null, req.session.name || '']));
    res.json({ success: true });
  } catch (err) { sendServerError(res, err); }
});

// Manager: day plans from CSV — rows [{ line, salesman, date, plan }].
